// ================= TAMPILAN TERMUX (banner pelangi + tabel info) =================
const ANSI_RE = /\x1b\[[0-9;]*m/g;
const visLen = (t) => String(t).replace(ANSI_RE, "").length;
const fg = (r, g, b) => `\x1b[38;2;${r};${g};${b}m`;
const RST = "\x1b[0m", BOLD = "\x1b[1m", DIM = "\x1b[2m";
function hue2rgb(h) { // h 0..360 -> [r,g,b] (HSV penuh)
  h = ((h % 360) + 360) % 360;
  const f = (n) => { const k = (n + h / 60) % 6; return Math.round(255 * (1 - Math.max(0, Math.min(k, 4 - k, 1)))); };
  return [f(5), f(3), f(1)];
}
/** Warnai teks per kolom dengan gradasi pelangi */
function rainbowText(text, offset = 0, span = null) {
  const chars = [...text], n = span || Math.max(1, chars.length);
  return chars.map((ch, i) => (ch === " " ? ch : fg(...hue2rgb((offset + (i / n) * 330) % 360)) + ch)).join("") + RST;
}
const ZY_BIG = [
  ["███████╗", "╚══███╔╝", "  ███╔╝ ", " ███╔╝  ", "███████╗", "╚══════╝"],
  ["██╗   ██╗", "╚██╗ ██╔╝", " ╚████╔╝ ", "  ╚██╔╝  ", "   ██║   ", "   ╚═╝   "],
  ["███╗   ██╗", "████╗  ██║", "██╔██╗ ██║", "██║╚██╗██║", "██║ ╚████║", "╚═╝  ╚═══╝"],
  [" ██████╗ ", "██╔═══██╗", "██║   ██║", "██║   ██║", "╚██████╔╝", " ╚═════╝ "],
  ["██████╗ ", "██╔══██╗", "██████╔╝", "██╔══██╗", "██║  ██║", "╚═╝  ╚═╝"],
  [" █████╗ ", "██╔══██╗", "███████║", "██╔══██║", "██║  ██║", "╚═╝  ╚═╝"],
];
const ZY_SMALL = [
  ["▀▀█", "▄▀ ", "█▄▄"], ["█ █", " █ ", " █ "], ["█▄ █", "█ ▀█", "█  █"],
  ["▄▀▀▄", "█  █", "▀▄▄▀"], ["█▀█", "█▀▄", "▀ ▀"], ["▄▀▄", "█▀█", "▀ ▀"],
];
function zynoraBanner(cols = process.stdout.columns || 48) {
  const font = cols >= 58 ? ZY_BIG : ZY_SMALL, h = font[0].length;
  const rows = Array.from({ length: h }, (_, r) => font.map((l) => l[r]).join(cols >= 58 ? "" : " "));
  const w = Math.max(...rows.map((x) => x.length));
  const pad = " ".repeat(Math.max(0, Math.floor((cols - w) / 2)));
  const out = rows.map((r, i) => pad + BOLD + rainbowText(r, i * 14, w));
  const sub = "WhatsApp Bot • Termux Edition";
  out.push(pad + " ".repeat(Math.max(0, Math.floor((w - sub.length) / 2))) + DIM + rainbowText(sub, 40) );
  return out.join("\n");
}

const trimTo = (t, n) => { t = String(t); return t.length > n ? t.slice(0, Math.max(1, n - 1)) + "…" : t; };
function infoTable(title, rows, cols = process.stdout.columns || 48) {
  const total = Math.max(34, Math.min(cols - 1, 62));
  const lw = Math.max(...rows.map(([k]) => k.length)) + 2, vw = total - lw - 7;
  const cell = (t, w) => t + " ".repeat(Math.max(0, w - visLen(t)));
  const o = [];
  const tt = ` ${title} `, side = Math.max(0, total - 2 - tt.length);
  o.push(fg(120, 200, 255) + "╭" + "─".repeat(Math.floor(side / 2)) + RST + BOLD + rainbowText(tt, 0) + fg(120, 200, 255) + "─".repeat(Math.ceil(side / 2)) + "╮" + RST);
  rows.forEach(([k, v], i) => {
    const kc = fg(...hue2rgb((i * 70 + 10) % 360)) + BOLD + cell(k, lw) + RST;
    o.push(fg(120, 200, 255) + "│ " + RST + kc + fg(120, 200, 255) + " │ " + RST + cell(visLen(v) > vw ? trimTo(v.replace(ANSI_RE, ""), vw) : v, vw) + fg(120, 200, 255) + " │" + RST);
  });
  o.push(fg(120, 200, 255) + "╰" + "─".repeat(total - 2) + "╯" + RST);
  return o.join("\n");
}

let geoCache = { at: 0, v: null };
async function geoCountry() {
  if (geoCache.v && Date.now() - geoCache.at < 10 * 60 * 1000) return geoCache.v;
  for (const u of ["http://ip-api.com/json/?fields=status,country,countryCode,city&lang=id", "https://ipwho.is/?fields=success,country,country_code,city"]) {
    try {
      const ctl = new AbortController(); const t = setTimeout(() => ctl.abort(), 3500);
      const j = await (await fetch(u, { signal: ctl.signal })).json(); clearTimeout(t);
      if (j.status === "fail" || j.success === false || !j.country) continue;
      const cc = j.countryCode || j.country_code || "";
      geoCache = { at: Date.now(), v: `${j.country}${cc ? " (" + cc + ")" : ""}${j.city ? " • " + j.city : ""}` };
      return geoCache.v;
    } catch {}
  }
  return geoCache.v || "Tidak diketahui (offline)";
}
async function deviceName() {
  try {
    const [b, m] = await Promise.all([run("getprop", ["ro.product.brand"]), run("getprop", ["ro.product.model"])]);
    const brand = b.trim(), model = m.trim();
    if (model) return `${brand ? brand[0].toUpperCase() + brand.slice(1) + " " : ""}${model}`;
  } catch {}
  return `${os.hostname()} (${os.platform()} ${os.arch()})`;
}
async function batteryInfo() {
  let pct = null, st = "";
  try { const j = JSON.parse(await run("termux-battery-status", [], { timeout: 4000 })); pct = Math.round(j.percentage); st = String(j.status || "").toUpperCase(); } catch {}
  if (pct === null) {
    for (const d of ["/sys/class/power_supply/battery", "/sys/class/power_supply/BAT0"]) {
      try { pct = parseInt(fs.readFileSync(d + "/capacity", "utf8"), 10); st = fs.readFileSync(d + "/status", "utf8").trim().toUpperCase(); break; } catch {}
    }
  }
  if (pct === null || isNaN(pct)) return "Tidak terbaca (pasang Termux:API)";
  const n = Math.round(pct / 10), col = pct > 50 ? fg(80, 230, 120) : pct > 20 ? fg(255, 200, 60) : fg(255, 80, 80);
  const state = /CHARG/.test(st) && !/DISCH|NOT/.test(st) ? " (mengisi)" : "";
  return `${col}${"▰".repeat(n)}${"▱".repeat(10 - n)}${RST} ${pct}%${state}`;
}
