const formatTime = (ms) => {
  const s = Math.floor(ms / 1000);
  return `${Math.floor(s / 3600)}j ${Math.floor((s % 3600) / 60)}m ${s % 60}d`;
};

async function getBuf(url, headers = {}, opts = {}) {
  let host = url;
  try { host = new URL(url).hostname; } catch {}
  if (!opts.noBreaker && hostIsDown(host)) throw new Error(`host sedang tidak terjangkau, dilewati sementara @ ${host}`);
  const total = opts.timeout || 30000;
  // Batas waktu menunggu respons awal: pendek untuk API biasa (gagal cepat bila situs diblokir/macet),
  // panjang untuk panggilan yang memang lama diproses server (timeout >= 40 dtk).
  const headerMs = opts.headerTimeout ?? (total > 40000 ? total : Math.min(total, 10000));
  const ctl = new AbortController();
  let why = "";
  const tH = setTimeout(() => { why = "HEADER"; ctl.abort(); }, headerMs);
  const tT = setTimeout(() => { why = "TOTAL"; ctl.abort(); }, total);
  try {
    const res = await fetch(url, {
      method: opts.method || "GET",
      body: opts.body,
      headers: {
        "User-Agent": "Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 Chrome/120 Mobile Safari/537.36",
        ...headers,
      },
      signal: ctl.signal,
    });
    clearTimeout(tH);
    if (!res.ok) throw new Error("HTTP " + res.status);
    const buf = Buffer.from(await res.arrayBuffer());
    hostOk(host);
    return buf;
  } catch (e) {
    const code = e.cause?.code || "";
    if (why === "HEADER" || NET_CODES.test(code)) markHostDown(host);
    const msg = why === "HEADER" ? `tidak ada respons dalam ${Math.round(headerMs / 1000)} detik` : why === "TOTAL" ? `timeout ${Math.round(total / 1000)} detik` : e.message;
    throw new Error(`${msg}${code ? " (" + code + ")" : ""} @ ${host}`);
  } finally { clearTimeout(tH); clearTimeout(tT); }
}

// ---------- Helper media ----------
async function streamToBuffer(stream) {
  const chunks = [];
  for await (const chunk of stream) chunks.push(chunk);
  return Buffer.concat(chunks);
}

const unwrap = (m) =>
  m?.viewOnceMessageV2?.message ||
  m?.viewOnceMessageV2Extension?.message ||
  m?.viewOnceMessage?.message ||
  m?.ephemeralMessage?.message ||
  m;

function pickMedia(msg) {
  const m = unwrap(msg.message) || {};
  const ctx = m.extendedTextMessage?.contextInfo || m.imageMessage?.contextInfo || m.videoMessage?.contextInfo;
  const quoted = unwrap(ctx?.quotedMessage);
  for (const src of [m, quoted]) {
    if (!src) continue;
    for (const t of ["imageMessage", "videoMessage", "audioMessage", "stickerMessage"]) {
      if (src[t]) return { type: t.replace("Message", ""), content: src[t] };
    }
  }
  return null;
}

function pickViewOnce(msg) {
  const m = unwrap(msg.message) || {};
  const q = m.extendedTextMessage?.contextInfo?.quotedMessage;
  if (!q) return null;
  const inner = unwrap(q);
  for (const t of ["imageMessage", "videoMessage", "audioMessage"]) {
    if (inner?.[t] && (inner[t].viewOnce || q.viewOnceMessage || q.viewOnceMessageV2 || q.viewOnceMessageV2Extension)) {
      return { type: t.replace("Message", ""), content: inner[t] };
    }
  }
  return null;
}

async function download(media) {
  const stream = await downloadContentFromMessage(media.content, media.type);
  return streamToBuffer(stream);
}

// ---------- Stiker ----------
const STICKER_VF =
  "scale=512:512:force_original_aspect_ratio=decrease,fps=15,format=rgba," +
  "pad=512:512:(ow-iw)/2:(oh-ih)/2:color=#00000000";

async function toSticker(buffer, isVideo) {
  const inp = tmpFile(isVideo ? "mp4" : "jpg");
  const out = tmpFile("webp");
  fs.writeFileSync(inp, buffer);
  const args = ["-y", "-i", inp];
  if (isVideo) args.push("-t", "8");
  args.push("-vf", STICKER_VF, "-c:v", "libwebp", "-loop", "0", "-an", "-q:v", "55", "-preset", "default", out);
  try {
    await run("ffmpeg", args);
    return fs.readFileSync(out);
  } finally { cleanup(inp, out); }
}

