const NEED_YTDLP = "⚠️ yt-dlp belum terinstall.\nJalankan di Termux:\n`pkg install python -y && pip install -U yt-dlp`";
let ytdlpFound = false; // hasil positif disimpan, tidak perlu memanggil python tiap unduhan
async function hasYtdlp() {
  if (ytdlpFound) return true;
  try { await run("yt-dlp", ["--version"], { timeout: 15000 }); ytdlpFound = true; return true; } catch { return false; }
}
async function ytdlp(url, mode, extra = []) {
  const base = path.join(TMP, "dl_" + Date.now() + "_" + Math.random().toString(36).slice(2, 6));
  const args = ["--no-playlist", "--no-warnings", "--max-filesize", "60M", "-o", base + ".%(ext)s", "--print", "%(title)s", "--no-simulate"];
  const cookies = path.join(__dirname, "cookies.txt");
  if (fs.existsSync(cookies)) args.push("--cookies", cookies);
  if (mode === "audio") args.push("-x", "--audio-format", "m4a");
  else args.push("-f", "bv*[height<=720]+ba/b[height<=720]/b", "--merge-output-format", "mp4");
  args.push(...extra, url);
  const out = await run("yt-dlp", args, { timeout: 300000 });
  const title = (out.trim().split("\n")[0] || "").slice(0, 150);
  const prefix = path.basename(base) + ".";
  const files = fs.readdirSync(TMP).filter((f) => f.startsWith(prefix)).map((f) => path.join(TMP, f));
  const file = files.find((f) => /\.(mp4|m4a)$/.test(f)) || files[0];
  if (!file) throw new Error("yt-dlp: file hasil tidak ditemukan");
  files.filter((f) => f !== file).forEach((f) => cleanup(f));
  return { file, title };
}

const looksBlocked = (raw) => /just a moment|cf-chl|challenge-platform|<html/i.test(String(raw).slice(0, 600));
const blockHint = (m) => (/HTTP (403|429|503)/.test(m) ? m + " (kemungkinan verifikasi bot)" : m);

async function tikwm(url) {
  const errs = [];
  // Sumber 1: TikWM (sering kena verifikasi bot)
  try {
    const raw = (await getBuf(
      "https://www.tikwm.com/api/",
      { "Content-Type": "application/x-www-form-urlencoded" },
      { method: "POST", body: new URLSearchParams({ url, hd: "1" }).toString() }
    )).toString();
    if (looksBlocked(raw)) throw new Error("diblokir verifikasi bot");
    const json = JSON.parse(raw);
    if (json.code === 0 && json.data) return json.data;
    throw new Error(json.msg || "gagal");
  } catch (e) { errs.push("tikwm: " + blockHint(e.message)); }
  // Sumber 2: Tiklydown
  try {
    const raw = (await getBuf(`https://api.tiklydown.eu.org/api/download/v3?url=${encodeURIComponent(url)}`)).toString();
    if (looksBlocked(raw)) throw new Error("diblokir verifikasi bot");
    const j = JSON.parse(raw);
    const v = j.result || j;
    const play = v.video?.noWatermark || v.video?.nowm || v.video?.watermark;
    const images = v.images || v.image || [];
    if (!play && !images.length) throw new Error("data video kosong");
    return {
      play,
      hdplay: play,
      music: v.music?.play_url || (typeof v.music === "string" ? v.music : null),
      images: Array.isArray(images) ? images : [],
      title: v.title || "TikTok",
    };
  } catch (e) { errs.push("tiklydown: " + blockHint(e.message)); }
  throw new Error(errs.join(" | "));
}
const absTikwm = (u) => (u && u.startsWith("/") ? "https://www.tikwm.com" + u : u);

const aiHistory = new Map();
const aiHistoryAt = new Map();
function aiSystem(name) {
  const now = new Date().toLocaleString("id-ID", { dateStyle: "full", timeStyle: "short", timeZone: "Asia/Jakarta" });
  return `Kamu SkyBot, asisten WhatsApp buatan SkyDev (owner: Alvarenza).${name ? ` Kamu sedang berbicara dengan ${name}.` : ""} Sekarang: ${now} WIB.
Aturan jawaban:
- Pakai bahasa yang dipakai pengguna (default Indonesia). Langsung ke inti: tanpa basa-basi pembuka/penutup dan tanpa mengulang pertanyaan.
- Format WhatsApp: *tebal*, _miring_, daftar dengan "- ". Jangan pakai heading "#", tabel, atau "**".
- Kode selalu dalam blok \`\`\`.
- Jika pengguna membalas sebuah pesan lalu memberi perintah (terjemahkan, rangkum, perbaiki, balas, jelaskan, dll), kerjakan perintah itu pada pesan tersebut dan berikan HASILNYA saja.
- Jika permintaan ambigu, tanyakan satu pertanyaan singkat. Jangan mengarang fakta; akui jika tidak tahu.`;
}

/** Ubah Markdown model AI menjadi format WhatsApp */
function toWhatsApp(t) {
  let inCode = false;
  return String(t).split("\n").map((line) => {
    if (/^\s*```/.test(line)) { inCode = !inCode; return line; }
    if (inCode) return line;
    line = line.replace(/^\s{0,3}#{1,6}\s+(.*?)\s*#*\s*$/, "*$1*");
    line = line.replace(/^(\s*)[*+]\s+/, "$1- ");
    line = line.replace(/\*\*(.+?)\*\*/g, "*$1*").replace(/__(.+?)__/g, "_$1_");
    line = line.replace(/^\s*[-*_]{3,}\s*$/, "──────────");
    return line;
  }).join("\n").replace(/\n{3,}/g, "\n\n").trim();
}

// id pesan jawaban AI -> user bisa membalasnya tanpa perintah untuk melanjutkan obrolan
const aiMsgIds = new Map();
function rememberAiMsg(sent) {
  const id = sent?.key?.id;
  if (!id) return;
  aiMsgIds.set(id, Date.now());
  if (aiMsgIds.size > 500) aiMsgIds.delete(aiMsgIds.keys().next().value);
}
function aiRemember(key, userText, answer) {
  const hist = aiHistory.get(key) || [];
  hist.push({ role: "user", content: userText }, { role: "assistant", content: answer });
  aiHistory.set(key, hist.slice(-20)); aiHistoryAt.set(key, Date.now());
}

// ---------- Gemini (Google AI Studio, key format AQ. / AIza) ----------
const GEMINI_BASE = "https://generativelanguage.googleapis.com/v1beta";
const GEMINI_FALLBACK_MODELS = ["gemini-3.8-flash", "gemini-3.7-flash", "gemini-3.6-flash"];
const geminiCache = { models: null, at: 0 };
const GEMINI_HOST = "generativelanguage.googleapis.com";
const geminiNoThink = new Set();

async function geminiFetch(urlPath, { method = "GET", body, timeout = 60000 } = {}) {
  let res;
  if (hostIsDown(GEMINI_HOST)) throw new Error("Gemini tidak terjangkau (dilewati sementara karena gagal beruntun, coba lagi beberapa menit)");
  try {
    const call = (url, hdr) => fetch(url, { method, headers: { ...hdr, "Content-Type": "application/json" }, body, signal: AbortSignal.timeout(timeout) });
    res = await call(GEMINI_BASE + urlPath, { "x-goog-api-key": process.env.GEMINI_API_KEY });
    if (res.status === 401) { // coba cara lain: key lewat parameter URL
      const alt = await call(GEMINI_BASE + urlPath + (urlPath.includes("?") ? "&" : "?") + "key=" + encodeURIComponent(process.env.GEMINI_API_KEY), {});
      if (alt.ok) res = alt;
    }
  } catch (e) {
    const netDown = NET_CODES.test(String(e.cause?.code || "")), timedOut = e.name === "TimeoutError" || e.name === "AbortError";
    if (netDown || (timedOut && method === "GET")) markHostDown(GEMINI_HOST); // model yang lambat tidak berarti Gemini mati
    const model = (urlPath.match(/\/models\/([^:/?]+)/) || [])[1];
    const err = new Error(timedOut
      ? `Gemini${model ? " (" + model + ")" : ""} tidak menjawab dalam ${Math.round(timeout / 1000)} detik`
      : `Gemini tidak terjangkau (${e.cause?.code || e.name || e.message}). Jika ENOTFOUND, ganti DNS pribadi Android ke dns.google.`);
    err.timeout = timedOut; err.netDown = netDown;
    throw err;
  }
  hostOk(GEMINI_HOST);
  const text = await res.text();
  let j = null;
  try { j = JSON.parse(text); } catch {}
  if (!res.ok) {
    const hint = res.status === 401 || res.status === 403 ? " → Key ditolak Google. Buat key baru di aistudio.google.com/api-keys, salin dengan tombol Copy, lalu kirim ulang lewat .setkey" : "";
    const e = new Error(`Gemini HTTP ${res.status}: ${String(j?.error?.message || text).replace(/\s+/g, " ").slice(0, 140)}${hint}`);
    e.status = res.status;
    throw e;
  }
  return j;
}

/** Daftar model Flash terbaru yang dipakai (otomatis, karena nama model Gemini sering berganti) */
async function geminiModels(strict = false) {
  const forced = process.env.GEMINI_MODEL ? [process.env.GEMINI_MODEL] : [];
  if (!strict && geminiCache.models && Date.now() - geminiCache.at < 6 * 3600 * 1000) return [...forced, ...geminiCache.models];
  let found = [];
  try {
    const j = await geminiFetch("/models?pageSize=200", { timeout: 8000 });
    found = (j.models || [])
      .filter((m) => (m.supportedGenerationMethods || []).includes("generateContent"))
      .map((m) => String(m.name).replace(/^models\//, ""))
      .map((n) => { const mt = n.match(/^gemini-(\d+)(?:\.(\d+))?-flash$/); return mt ? { n, v: [+mt[1], +(mt[2] || 0)] } : null; })
      .filter(Boolean)
      .sort((x, y) => y.v[0] - x.v[0] || y.v[1] - x.v[1])
      .slice(0, 3)
      .map((x) => x.n);
  } catch (e) { if (strict) throw e; }
  if (!found.length) found = GEMINI_FALLBACK_MODELS;
  geminiCache.models = found; geminiCache.at = Date.now();
  return [...forced, ...found.filter((m) => m !== forced[0])];
}

const geminiSlow = new Map(); // model -> waktu timeout terakhir (diturunkan prioritasnya 15 menit)
const geminiLast = { model: "", ms: 0 };
/** Panggil Gemini. Model kena kuota/hilang/lambat -> otomatis coba model berikutnya (model stabil 2.5 selalu ikut sebagai cadangan). */
async function geminiGenerate({ system = aiSystem(), contents, maxTokens = 4096, timeout = 60000 }) {
  const found = await geminiModels();
  let models = [...new Set([found[0], "gemini-2.5-flash", ...found.slice(1), "gemini-2.5-flash-lite"])].filter(Boolean);
  const nowT = Date.now(), slow = (m) => nowT - (geminiSlow.get(m) || 0) < 15 * 60 * 1000;
  models = [...models.filter((m) => !slow(m)), ...models.filter(slow)];
  const discovered = new Set(found);
  let lastErr, timeouts = 0, first = true;
  for (const model of models) {
    const tmo = first ? timeout : Math.min(timeout, 20000); first = false;
    for (const think of geminiNoThink.has(model) ? [false] : [true, false]) {
      const gen = { maxOutputTokens: maxTokens };
      if (think) gen.thinkingConfig = { thinkingLevel: "low" };
      const t0 = Date.now();
      try {
        const j = await geminiFetch(`/models/${model}:generateContent`, {
          method: "POST", timeout: tmo,
          body: JSON.stringify({ systemInstruction: system ? { parts: [{ text: system }] } : undefined, contents, generationConfig: gen }),
        });
        const text = (j.candidates?.[0]?.content?.parts || []).map((p) => p.text || "").join("").trim();
        if (text) { geminiLast.model = model; geminiLast.ms = Date.now() - t0; return text; }
        const why = j.promptFeedback?.blockReason || j.candidates?.[0]?.finishReason;
        const e = new Error("Gemini tidak memberi jawaban" + (why ? ` (${why})` : ""));
        e.status = 0; throw e;
      } catch (e) {
        lastErr = e;
        if (e.timeout) { geminiSlow.set(model, Date.now()); if (++timeouts >= 3) throw e; break; } // model lambat: coba model lain
        if (e.netDown) throw e;
        if (think && e.status === 400) { geminiNoThink.add(model); continue; } // model tidak mengenal thinkingConfig: ulangi tanpa itu (diingat)
        if (e.status === 404 && discovered.has(model)) geminiCache.models = null;
        if (![404, 429, 500, 503].includes(e.status)) throw e;
        break; // coba model berikutnya
      }
    }
  }
  throw lastErr || new Error("Gemini gagal");
}
/** Uji nyata: minta Gemini menjawab satu kata (untuk .diagnosa). */
async function geminiProbe() {
  await geminiGenerate({ system: "", contents: [{ role: "user", parts: [{ text: "Balas satu kata saja: ok" }] }], maxTokens: 16, timeout: 20000 });
  return { model: geminiLast.model, ms: geminiLast.ms };
}
let geminiImgOffUntil = 0;
/** Edit foto dengan Gemini 2.5 Flash Image (kuota gratis dari key Gemini yang sama). Mengembalikan buffer gambar. */
async function geminiEditImage(buf, prompt) {
  const model = process.env.GEMINI_IMAGE_MODEL || "gemini-2.5-flash-image";
  const j = await geminiFetch(`/models/${model}:generateContent`, {
    method: "POST", timeout: 90000,
    body: JSON.stringify({ contents: [{ role: "user", parts: [{ text: prompt }, { inlineData: { mimeType: imageMime(buf), data: buf.toString("base64") } }] }] }),
  });
  const part = (j.candidates?.[0]?.content?.parts || []).find((p) => (p.inlineData || p.inline_data)?.data);
  const d = part && (part.inlineData || part.inline_data);
  if (!d) { const why = j.promptFeedback?.blockReason || j.candidates?.[0]?.finishReason; const e = new Error("Gemini tidak mengembalikan gambar" + (why ? ` (${why})` : "")); e.status = 0; throw e; }
  return Buffer.from(d.data, "base64");
}

const imageMime = (b) => (b[0] === 0x89 ? "image/png" : b.slice(0, 4).toString() === "RIFF" ? "image/webp" : "image/jpeg");
const toGeminiContents = (messages) => messages.map((m) => ({ role: m.role === "assistant" ? "model" : "user", parts: [{ text: m.content }] }));

// Cadangan berurutan: Claude (bila ada key) -> Groq (key gratis) -> Pollinations
async function askAIFallback(system, messages) {
  const tries = [];
  if (process.env.ANTHROPIC_API_KEY) tries.push(["Claude", async () => {
    const raw = await getBuf("https://api.anthropic.com/v1/messages",
      { "content-type": "application/json", "x-api-key": process.env.ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01" },
      { method: "POST", timeout: 30000, body: JSON.stringify({ model: "claude-haiku-5-5", max_tokens: 1000, system, messages }) });
    return (JSON.parse(raw.toString()).content || []).map((c) => c.text || "").join("");
  }]);
  if (process.env.GROQ_API_KEY) tries.push(["Groq", async () => {
    const raw = await getBuf("https://api.groq.com/openai/v1/chat/completions",
      { "Content-Type": "application/json", Authorization: `Bearer ${process.env.GROQ_API_KEY}` },
      { method: "POST", timeout: 30000, body: JSON.stringify({ model: process.env.GROQ_MODEL || "llama-3.3-70b-versatile", messages: [{ role: "system", content: system }, ...messages], max_tokens: 1000 }) });
    return JSON.parse(raw.toString()).choices?.[0]?.message?.content || "";
  }]);
  tries.push(["Pollinations", async () => {
    const raw = await getBuf("https://text.pollinations.ai/openai", { "Content-Type": "application/json" },
      { method: "POST", timeout: 30000, body: JSON.stringify({ model: "openai", messages: [{ role: "system", content: system }, ...messages] }) });
    return JSON.parse(raw.toString()).choices?.[0]?.message?.content || "";
  }]);
  const errs = [];
  for (const [name, fn] of tries) {
    try { const a = await fn(); if (a) return a; errs.push(`${name}: kosong`); }
    catch (e) { errs.push(`${name}: ${String(e.message).slice(0, 80)}`); }
  }
  throw new Error(errs.join(" | "));
}

async function askAI(key, prompt, opts = {}) {
  const system = aiSystem(opts.name);
  const hist = aiHistory.get(key) || [];
  hist.push({ role: "user", content: prompt });
  let messages = hist.slice(-10);
  while (messages.length && messages[0].role !== "user") messages.shift();
  let answer = "", gErr = null;
  if (process.env.GEMINI_API_KEY) {
    try { answer = await geminiGenerate({ system, contents: toGeminiContents(messages), timeout: Number(process.env.GEMINI_TIMEOUT_MS) || 25000 }); }
    catch (e) { gErr = e; console.log("Gemini gagal, pakai cadangan:", e.message); }
  }
  if (!answer) {
    try { answer = await askAIFallback(system, messages); }
    catch (e) { throw gErr ? new Error(`${gErr.message} | cadangan: ${e.message}`) : e; }
  }
  if (!answer) throw new Error("AI tidak memberi jawaban");
  hist.push({ role: "assistant", content: answer });
  aiHistory.set(key, hist.slice(-10)); aiHistoryAt.set(key, Date.now());
  return answer.trim();
}

// ================= MENFESS / CONFESS: obrolan anonim 2 arah =================
// Alur: pengirim memakai .menfess/.confess -> bot mengirim pesan ke tujuan. Begitu tujuan membalas (reply atau ketik biasa),
// jendela 5 menit terbuka: pesan tujuan diteruskan ke pengirim, dan pesan pengirim diteruskan ke tujuan, langsung tanpa perintah.
const FESS_WINDOW = 5 * 60 * 1000;      // lama obrolan, dihitung sejak tujuan pertama kali membalas
const FESS_PENDING = 24 * 3600 * 1000;  // batas menunggu tujuan membalas
const fessTimers = new Map();
const fessSent = new Set();   // id pesan yang dikirim bot sendiri lewat relay (tidak boleh diproses ulang -> mencegah loop)
let fessBurst = [];            // pemutus darurat: terlalu banyak relay dalam waktu singkat
async function fessSend(sk, to, content) {
  const sent = await sk.sendMessage(to, content);
  const id = sent?.key?.id;
  if (id) { fessSent.add(id); if (fessSent.size > 3000) fessSent.delete(fessSent.values().next().value); }
  return sent;
}
const fessLive = (r) => !r.closed && r.start && Date.now() < r.start + FESS_WINDOW;
const fessWaiting = (r) => !r.closed && !r.start && Date.now() - r.time < FESS_PENDING;

function closeFess(id, notify = true) {
  const r = db.menfess[id];
  if (!r || r.closed) return;
  r.closed = true;
  clearTimeout(fessTimers.get(id)); fessTimers.delete(id);
  saveDB();
  const sk = getSock();
  if (!notify || !sk) return;
  const lbl = r.type === "CONFESS" ? "confess" : "menfess";
  fessSend(sk, jidOf(r.from), { text: `⌛ Waktu *5 menit* obrolan ${lbl} sudah habis. Sesi ditutup.\nIngin lanjut? Kirim ${lbl} baru dengan *.${lbl}*.` }).catch(() => {});
  fessSend(sk, jidOf(r.to), { text: `⌛ Waktu *5 menit* obrolan anonim dengan *${r.alias}* sudah habis. Sesi ditutup.` }).catch(() => {});
}

/** Teruskan pesan biasa (bukan perintah) di chat pribadi bila terkait sesi menfess/confess. true = sudah ditangani. */
async function fessRelay(sock, msg, senderNum, body, cinfo) {
  if (settings.fessOff) return false;                    // fitur dimatikan owner
  if (msg.key.fromMe) return false;                       // pesan dari perangkat/nomor bot sendiri: jangan pernah diteruskan
  if (fessSent.has(msg.key.id)) return false;             // pesan hasil relay bot
  if (numOf(msg.key.remoteJid || "") !== senderNum) return false; // hanya chat pribadi milik pengirim itu sendiri
  const entries = Object.entries(db.menfess);
  if (!entries.length) return false;
  for (const [id, r] of entries) if (r.start && !r.closed && Date.now() >= r.start + FESS_WINDOW) closeFess(id);
  const stanza = cinfo?.stanzaId;
  let pick = null; // { id, r, role }
  const score = (r, role, id) => {
    let sc = 0;
    if (role === "to" && stanza && (r.msgIds || []).includes(stanza)) sc += 1000; // membalas langsung pesan menfess
    if (fessLive(r)) sc += 100;
    return sc + r.time / 1e13;
  };
  let best = -1;
  for (const [id, r] of entries) {
    let role = null;
    if (r.to === senderNum && (fessLive(r) || fessWaiting(r))) role = "to";
    else if (r.from === senderNum && fessLive(r)) role = "from";
    if (!role) continue;
    const sc = score(r, role, id);
    if (sc > best) { best = sc; pick = { id, r, role }; }
  }
  if (!pick) return false;
  const { id, r, role } = pick;
  const nowT = Date.now();
  fessBurst = fessBurst.filter((t) => nowT - t < 10000); fessBurst.push(nowT);
  if (fessBurst.length > 12 || (r.n || 0) >= 80) { // pemutus darurat: tutup sesi diam-diam
    r.closed = true; clearTimeout(fessTimers.get(id)); fessTimers.delete(id); saveDB();
    console.log("Menfess: pemutus darurat aktif untuk", id);
    return true;
  }
  const isMedia = /^(image|video|audio|sticker|document|contact|location)Message$/.test(Object.keys(unwrap(msg.message) || {})[0] || "");
  const text = String(body || "").trim();
  if (!text && !isMedia) return false;
  if (text.length > 1500) { await fessSend(sock, jidOf(senderNum), { text: "Pesan terlalu panjang (maks 1500 karakter)." }, { quoted: msg }).catch(() => {}); return true; }
  const peer = jidOf(role === "to" ? r.from : r.to);
  const who = role === "to" ? "Penerima" : r.alias;
  const opening = role === "to" && !r.start;
  if (opening) { // balasan pertama dari tujuan: jendela 5 menit mulai dihitung
    r.start = Date.now();
    fessTimers.set(id, setTimeout(() => closeFess(id), FESS_WINDOW + 500));
    await fessSend(sock, peer, { text: `📩 *${r.type} ${id} dibalas!*\n⏳ Kamu punya *5 menit* untuk ngobrol. Ketik langsung di sini, pesanmu otomatis diteruskan ke penerima.` }).catch(() => {});
    await fessSend(sock, jidOf(r.to), { text: `⏳ Obrolan anonim dengan *${r.alias}* dibuka selama *5 menit*. Ketik langsung di sini untuk lanjut ngobrol.` }).catch(() => {});
  }
  try {
    if (text) await fessSend(sock, peer, { text: `💬 *${who}:*\n${text}` });
    else { await fessSend(sock, peer, { text: `💬 *${who}* mengirim:` }); await fessSend(sock, peer, { forward: msg }); }
  } catch (e) {
    await fessSend(sock, jidOf(senderNum), { text: "⚠️ Pesan gagal diteruskan. Coba lagi." }, { quoted: msg }).catch(() => {});
    return true;
  }
  r.n = (r.n || 0) + 1;
  saveDB();
  sock.sendMessage(jidOf(senderNum), { react: { text: "✅", key: msg.key } }).catch(() => {});
  return true;
}

