// ================= UMUM =================
let currentSock = null; // socket aktif (dipakai timer agar tetap valid setelah reconnect)
const getSock = () => currentSock;
const jidOf = (n) => `${n}@s.whatsapp.net`;
const USAGE_RE = /^(Contoh|Reply|Kirim\/reply|Atau reply|Format|Hanya |Maksimal|Teks terlalu|Video maksimal|Pesan terlalu|Modul |⚠️ yt-dlp|⏰ \*Format|🐞 \*Format|💌 \*Format|💘 \*Format|Waktu minimal|Kota |Tidak ditemukan|Ekspresi|Hasil tidak|Nomor tujuan|Tidak ada soal|PDF |Kode terlalu|Nomor tidak|Foto terlalu|Gambar terlalu|Fitur ini butuh|Kulit tidak|Batas video|Masih ada video|Antrean video|Batas edit AI|Masih ada edit AI|Antrean edit AI)/;

const fmtDur = (ms) => {
  const s = Math.round(ms / 1000);
  if (s < 60) return s + " detik";
  if (s < 3600) return Math.round(s / 60) + " menit";
  if (s < 86400) return (s / 3600).toFixed(s % 3600 ? 1 : 0) + " jam";
  return (s / 86400).toFixed(s % 86400 ? 1 : 0) + " hari";
};
const afkNoticeAt = new Map();
function pruneCaches(now = Date.now()) {
  for (const [k, t] of afkNoticeAt) if (now - t > 10 * 60 * 1000) afkNoticeAt.delete(k);
  for (const [k, t] of aiMsgIds) if (now - t > 6 * 3600 * 1000) aiMsgIds.delete(k);
  for (const [k, t] of aiHistoryAt) if (now - t > 12 * 3600 * 1000) { aiHistoryAt.delete(k); aiHistory.delete(k); }
  for (const [k, t] of emojiMiss) if (now - t > 10 * 60 * 1000) { emojiMiss.delete(k); emojiCache.delete(k); }
  while (danRecent.size > 300) danRecent.delete(danRecent.keys().next().value);
  while (gmCache.size > 300) gmCache.delete(gmCache.keys().next().value);
  try { // berkas sementara lebih dari 1 jam
    for (const f of fs.readdirSync(TMP)) {
      const p = path.join(TMP, f);
      if (p === EMOJI_DIR) continue;
      const st = fs.statSync(p);
      if (st.isFile() && now - st.mtimeMs > 3600 * 1000) fs.unlinkSync(p);
    }
  } catch {}
}
setInterval(pruneCaches, 30 * 60 * 1000).unref();
const durText = (ms) => {
  const m = Math.floor(ms / 60000);
  if (m < 1) return Math.max(1, Math.round(ms / 1000)) + " detik";
  if (m < 60) return m + " menit";
  const h = Math.floor(m / 60), mm = m % 60;
  if (h < 24) return h + " jam" + (mm ? " " + mm + " menit" : "");
  const d = Math.floor(h / 24), hh = h % 24;
  return d + " hari" + (hh ? " " + hh + " jam" : "");
};
function parseDuration(str) {
  const m = String(str).match(/^(\d+)\s*(detik|dtk|s|menit|mnt|m|jam|j|h|hari|d)\b/i);
  if (!m) return null;
  const n = parseInt(m[1], 10);
  const u = m[2].toLowerCase();
  const mult = ["detik", "dtk", "s"].includes(u) ? 1000 : ["menit", "mnt", "m"].includes(u) ? 60000 : ["jam", "j", "h"].includes(u) ? 3600000 : 86400000;
  return { ms: n * mult, rest: String(str).slice(m[0].length).trim() };
}
function parseNum(s) {
  s = String(s).trim();
  if (/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) return parseFloat(s.replace(/\./g, "").replace(",", "."));
  return parseFloat(s.replace(",", "."));
}

// ---------- Cache metadata grup & cek admin ----------
const gmCache = new Map();
async function groupMetaCached(sock, jid) {
  const c = gmCache.get(jid);
  if (c && Date.now() - c.t < 60000) return c.meta;
  const meta = await sock.groupMetadata(jid);
  gmCache.set(jid, { t: Date.now(), meta });
  return meta;
}
async function isGroupAdmin(sock, jid, num) {
  try {
    const meta = await groupMetaCached(sock, jid);
    return meta.participants.some((p) => p.admin && numOf(p.id) === num);
  } catch { return false; }
}

// ---------- Anti-spam grup ----------
const spamMap = new Map();
async function checkSpam(sock, jid, sender, senderNum, isOwner) {
  if (!settings.antispam[jid] || isOwner) return;
  const now = Date.now();
  const key = jid + "|" + senderNum;
  let st = spamMap.get(key);
  if (!st) { st = { times: [], warns: 0, last: 0 }; spamMap.set(key, st); }
  if (now - st.last > 10 * 60 * 1000) st.warns = 0;
  st.times = st.times.filter((t) => now - t < 8000);
  st.times.push(now);
  if (st.times.length < 6) return; // 6 pesan dalam 8 detik = spam
  if (await isGroupAdmin(sock, jid, senderNum)) return;
  st.times = [];
  st.warns++;
  st.last = now;
  if (st.warns >= 3) {
    st.warns = 0;
    await sock.sendMessage(jid, { text: `🚫 @${senderNum} dikeluarkan karena *spam*.`, mentions: [sender] });
    try { await sock.groupParticipantsUpdate(jid, [sender], "remove"); } catch {}
  } else {
    await sock.sendMessage(jid, { text: `⚠️ @${senderNum} terdeteksi *spam* (peringatan ${st.warns}/3).\nBerhenti kirim pesan beruntun ya!`, mentions: [sender] });
  }
}

// ---------- Anti-delete ----------
const msgCache = new Map();
function cacheMsg(msg) {
  if (msg.key.fromMe || !msg.message || msg.message.protocolMessage) return;
  msgCache.set(msg.key.id, msg);
  if (msgCache.size > 400) msgCache.delete(msgCache.keys().next().value);
}
async function handleRevoke(sock, msg, pm) {
  const chat = msg.key.remoteJid;
  if (!settings.antidelete[chat]) return;
  const orig = msgCache.get(pm.key?.id);
  if (!orig) return;
  const who = orig.key.participant || orig.key.remoteJid;
  const inner = unwrap(orig.message) || {};
  const head = `🗑️ *Pesan dihapus* oleh @${numOf(who)}`;
  try {
    const text = inner.conversation || inner.extendedTextMessage?.text;
    if (text) return await sock.sendMessage(chat, { text: `${head}:\n\n${text}`, mentions: [who] });
    for (const t of ["imageMessage", "videoMessage", "audioMessage", "stickerMessage"]) {
      if (!inner[t]) continue;
      const type = t.replace("Message", "");
      const buf = await streamToBuffer(await downloadContentFromMessage(inner[t], type));
      await sock.sendMessage(chat, { text: head, mentions: [who] });
      const cap = inner[t].caption || "";
      const payload =
        type === "image" ? { image: buf, caption: cap } :
        type === "video" ? { video: buf, caption: cap } :
        type === "audio" ? { audio: buf, mimetype: "audio/mp4", ptt: !!inner[t].ptt } : { sticker: buf };
      return await sock.sendMessage(chat, payload);
    }
  } catch {}
}

// ---------- Pengingat ----------
const scheduledRem = new Set();
function scheduleReminder(r) {
  if (scheduledRem.has(r.id)) return;
  scheduledRem.add(r.id);
  const delay = Math.min(Math.max(0, r.at - Date.now()), 2147483000);
  setTimeout(async () => {
    try { await getSock().sendMessage(r.jid, { text: `⏰ *PENGINGAT* @${numOf(r.who)}\n\n${r.text}`, mentions: [r.who] }); } catch {}
    db.reminders = db.reminders.filter((x) => x.id !== r.id);
    scheduledRem.delete(r.id);
    saveDB();
  }, delay);
}
function restoreReminders() { for (const r of db.reminders) scheduleReminder(r); }

// ================= PEMBUAT GAMBAR AI (berlapis) =================
async function generateImage(prompt) {
  const errs = [];
  const { CLOUDFLARE_ACCOUNT_ID: cfId, CLOUDFLARE_API_TOKEN: cfTok, HF_TOKEN: hf } = process.env;
  // 1) Cloudflare Workers AI (paling stabil, perlu token gratis)
  if (cfId && cfTok) {
    try {
      const raw = await getBuf(
        `https://api.cloudflare.com/client/v4/accounts/${cfId}/ai/run/@cf/black-forest-labs/flux-1-schnell`,
        { Authorization: `Bearer ${cfTok}`, "Content-Type": "application/json" },
        { method: "POST", timeout: 60000, body: JSON.stringify({ prompt, steps: 4 }) }
      );
      const j = JSON.parse(raw.toString());
      if (j.result?.image) return Buffer.from(j.result.image, "base64");
      throw new Error(j.errors?.[0]?.message || "respons tanpa gambar");
    } catch (e) { errs.push("cloudflare: " + e.message.slice(0, 80)); }
  }
  // 2) Hugging Face (opsional, perlu token gratis)
  if (hf) {
    try {
      const buf = await getBuf(
        "https://router.huggingface.co/hf-inference/models/black-forest-labs/FLUX.1-schnell",
        { Authorization: `Bearer ${hf}`, "Content-Type": "application/json" },
        { method: "POST", timeout: 60000, body: JSON.stringify({ inputs: prompt }) }
      );
      if (buf.length > 2000 && buf[0] !== 0x7b) return buf;
      throw new Error("respons bukan gambar");
    } catch (e) { errs.push("huggingface: " + e.message.slice(0, 80)); }
  }
  // 3) Pollinations (tanpa key, bisa lambat/dibatasi) - coba beberapa model
  for (const model of ["flux", "turbo"]) {
    for (let i = 0; i < 2; i++) {
      try {
        const buf = await getBuf(
          `https://image.pollinations.ai/prompt/${encodeURIComponent(prompt)}?width=1024&height=1024&nologo=true&model=${model}&seed=${Math.floor(Math.random() * 1e6)}`,
          {}, { timeout: 60000 }
        );
        if (buf.length > 2000 && buf[0] !== 0x7b && buf[0] !== 0x3c) return buf;
        throw new Error("respons bukan gambar");
      } catch (e) { errs.push(`pollinations(${model}): ${e.message.slice(0, 60)}`); await sleep(2500); }
    }
  }
  throw new Error(errs.slice(-3).join(" | "));
}

// ================= STIKER MEME, ATTP, OCR, EFEK AUDIO =================
function wrapText(ctx, text, maxW) {
  const lines = [];
  let cur = "";
  for (const w of String(text).split(/\s+/).filter(Boolean)) {
    const t = cur ? cur + " " + w : w;
    if (!cur || ctx.measureText(t).width <= maxW) cur = t;
    else { lines.push(cur); cur = w; }
  }
  if (cur) lines.push(cur);
  return lines;
}

/** Bungkus teks jadi baris yang seimbang (tidak ada baris yatim berisi satu kata pendek). */
function balancedWrap(ctx, text, maxW) {
  const greedy = wrapText(ctx, text, maxW);
  const n = greedy.length;
  if (n <= 1) return greedy;
  const words = String(text).split(/\s+/).filter(Boolean);
  let lo = Math.min(Math.max(...words.map((w) => ctx.measureText(w).width)), maxW), hi = maxW;
  for (let i = 0; i < 14; i++) { const mid = (lo + hi) / 2; if (wrapText(ctx, text, mid).length <= n) hi = mid; else lo = mid; }
  return wrapText(ctx, text, hi);
}

async function makeMeme(buf, top, bottom) {
  setupFont();
  const img = await canvasLib.loadImage(buf);
  const scale = 512 / Math.max(img.width, img.height);
  const w = Math.round(img.width * scale), h = Math.round(img.height * scale);
  const c = canvasLib.createCanvas(w, h);
  const ctx = c.getContext("2d");
  ctx.drawImage(img, 0, 0, w, h);
  const both = !!(top && bottom);
  const draw = (text, atTop) => {
    if (!text) return;
    text = text.toUpperCase();
    const blockMax = h * (both ? 0.36 : 0.46); // tinggi maksimal satu blok teks
    let size = Math.min(Math.round(w / 6), Math.floor(blockMax / 1.1)), lines;
    for (; size >= 14; size -= 2) {
      ctx.font = `bold ${size}px ${FONT_NAME}`;
      lines = balancedWrap(ctx, text, w * 0.94);
      if (lines.length <= 4 && lines.length * size * 1.1 <= blockMax) break;
    }
    if (size < 14) { size = 14; ctx.font = `bold ${size}px ${FONT_NAME}`; lines = balancedWrap(ctx, text, w * 0.94); }
    ctx.font = `bold ${size}px ${FONT_NAME}`;
    ctx.textAlign = "center";
    ctx.textBaseline = "top";
    ctx.fillStyle = "#ffffff";
    ctx.strokeStyle = "#000000";
    ctx.lineWidth = Math.max(2, size / 7);
    ctx.lineJoin = "round";
    const lh = size * 1.1;
    let y = atTop ? 8 : h - lines.length * lh - 8;
    for (const l of lines) { ctx.strokeText(l, w / 2, y); ctx.fillText(l, w / 2, y); y += lh; }
  };
  draw(top, true);
  draw(bottom, false);
  return c.toBuffer("image/png");
}

async function makeAttp(text, animated) {
  setupFont();
  const colors = ["#ff3b30", "#ff9500", "#ffcc00", "#34c759", "#00c7be", "#007aff", "#af52de", "#ff2d55"];
  const dir = path.join(TMP, "attp_" + Date.now());
  fs.mkdirSync(dir, { recursive: true });
  const out = tmpFile("webp");
  try {
    const n = animated ? colors.length : 1;
    for (let i = 0; i < n; i++) {
      const c = canvasLib.createCanvas(512, 512);
      const ctx = c.getContext("2d");
      let size, lines;
      for (size = 150; size >= 16; size -= 2) {
        ctx.font = `bold ${size}px ${FONT_NAME}`;
        lines = wrapText(ctx, text, 470);
        if (lines.length * size * 1.15 <= 470 && lines.every((l) => ctx.measureText(l).width <= 470)) break;
      }
      ctx.font = `bold ${size}px ${FONT_NAME}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillStyle = colors[i];
      ctx.strokeStyle = "#000000";
      ctx.lineWidth = Math.max(3, size / 10);
      ctx.lineJoin = "round";
      const lh = size * 1.15;
      let y = 256 - ((lines.length - 1) * lh) / 2;
      for (const l of lines) { ctx.strokeText(l, 256, y); ctx.fillText(l, 256, y); y += lh; }
      fs.writeFileSync(path.join(dir, `f_${String(i).padStart(2, "0")}.png`), c.toBuffer("image/png"));
    }
    await run("ffmpeg", [
      "-y", "-framerate", animated ? "6" : "1", "-i", path.join(dir, "f_%02d.png"),
      "-c:v", "libwebp", "-pix_fmt", "yuva420p", "-loop", "0", "-lossless", "0", "-q:v", "60", "-an", out,
    ]);
    return fs.readFileSync(out);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
    cleanup(out);
  }
}

async function ocrImage(buf) {
  const inp = tmpFile("jpg");
  fs.writeFileSync(inp, buf);
  try {
    for (const lang of ["ind+eng", "eng"]) {
      try {
        const t = (await run("tesseract", [inp, "stdout", "-l", lang], { timeout: 60000 })).trim();
        if (t) return t;
      } catch {}
    }
  } finally { cleanup(inp); }
  const form = new FormData();
  form.append("apikey", process.env.OCRSPACE_KEY || "helloworld");
  form.append("language", "eng");
  form.append("OCREngine", "2");
  form.append("file", new Blob([buf]), "image.jpg");
  const res = await fetch("https://api.ocr.space/parse/image", { method: "POST", body: form, signal: AbortSignal.timeout(60000) });
  const j = await res.json();
  const t = (j.ParsedResults || []).map((r) => r.ParsedText).join("\n").trim();
  if (!t) throw new Error((j.ErrorMessage && j.ErrorMessage[0]) || "teks tidak terdeteksi");
  return t;
}

