let tgCache = null;
async function loadTebakGambar() {
  if (tgCache) return tgCache;
  try {
    const raw = await getBuf("https://raw.githubusercontent.com/BochilTeam/database/master/games/tebakgambar.json", {}, { timeout: 20000 });
    const arr = JSON.parse(raw.toString());
    if (Array.isArray(arr) && arr.length) { tgCache = arr; return arr; }
  } catch {}
  return null;
}

async function renderRebus(emojis) {
  if (!canvasLib) return null;
  setupFont();
  const list = emojis.match(EMOJI_RE) || [];
  const imgs = [];
  for (const e of list) { const im = await getEmojiImg(e); if (!im) return null; imgs.push(im); }
  const size = 200, gap = 60;
  const total = imgs.length * size + (imgs.length - 1) * gap;
  const w = Math.max(512, total + 100), h = 340;
  const c = canvasLib.createCanvas(w, h);
  const ctx = c.getContext("2d");
  const g = ctx.createLinearGradient(0, 0, w, h);
  g.addColorStop(0, "#fff7d6");
  g.addColorStop(1, "#ffd6e8");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);
  let x = (w - total) / 2;
  for (let i = 0; i < imgs.length; i++) {
    ctx.drawImage(imgs[i], x, (h - size) / 2, size, size);
    x += size;
    if (i < imgs.length - 1) {
      ctx.fillStyle = "#444444";
      ctx.font = `bold 56px ${FONT_NAME}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText("+", x + gap / 2, h / 2);
      x += gap;
    }
  }
  return c.toBuffer("image/png");
}

async function startTebak(sock, jid, msg) {
  const caption = "🖼️ *TEBAK GAMBAR*\n⏳ Waktu 60 detik\n\nKetik jawabanmu langsung di chat!\n💡 *.hint* bantuan • 🏳️ *.nyerah* menyerah";
  let item = null;
  const arr = await loadTebakGambar();
  if (arr) {
    const it = arr[Math.floor(Math.random() * arr.length)];
    if (it?.img && it?.jawaban) {
      try {
        await sock.sendMessage(jid, { image: { url: it.img }, caption }, { quoted: msg });
        item = { answer: String(it.jawaban), hint: it.deskripsi || "" };
      } catch {}
    }
  }
  if (!item) {
    const [emo, ans] = REBUS[Math.floor(Math.random() * REBUS.length)];
    const png = await renderRebus(emo).catch(() => null);
    if (png) await sock.sendMessage(jid, { image: png, caption }, { quoted: msg });
    else await sock.sendMessage(jid, { text: `${caption}\n\n${emo}` }, { quoted: msg });
    item = { answer: ans, hint: "Gabungan emoji membentuk sebuah kata/frasa" };
  }
  const game = { ...item, timer: null };
  game.timer = setTimeout(() => {
    if (tebakGame.get(jid) !== game) return;
    tebakGame.delete(jid);
    getSock().sendMessage(jid, { text: `⏰ *Waktu habis!*\nJawabannya: *${game.answer}*` }).catch(() => {});
  }, 60000);
  tebakGame.set(jid, game);
}

async function tebakAnswer(sock, msg, jid, sender, senderNum, body) {
  const g = tebakGame.get(jid);
  if (!g) return false;
  const a = normAns(body);
  if (!a || !(a === normAns(g.answer) || (g.aliases || []).some((x) => normAns(x) === a))) return false;
  clearTimeout(g.timer);
  tebakGame.delete(jid);
  await sock.sendMessage(jid, { text: `🎉 @${senderNum} benar!\nJawaban: *${g.answer}*`, mentions: [sender] }, { quoted: msg });
  return true;
}

