const VERSION = "1.17.0";
// ================= MODERASI GRUP: anti-virtex & anti-toxic =================
function botIsAdmin(sock, meta) {
  const ids = [numOf(sock.user?.id || ""), numOf(sock.user?.lid || "")].filter(Boolean);
  return meta.participants.some((p) => p.admin && [p.id, p.phoneNumber, p.lid].some((x) => x && ids.includes(numOf(x))));
}
const isParticipantAdmin = (meta, num) => meta.participants.some((p) => p.admin && [p.id, p.phoneNumber, p.lid].some((x) => x && numOf(x) === num));
/** Hapus pesan lalu buang dari cache antidelete, supaya tidak dikirim ulang oleh fitur antidelete. */
async function modDelete(sock, jid, msg) {
  msgCache.delete(msg.key.id);
  try { await sock.sendMessage(jid, { delete: msg.key }); } catch {}
}
const ZALGO_RE = /[\u0300-\u036f]/g;
const INVIS_RE = /[\u200b-\u200f\u202a-\u202e\u2060-\u206f\ufeff]/g;
/** kind "pattern" = pola virtex jelas (keluarkan pengirim); kind "length" = hanya sangat panjang (peringatan saja). */
function virtexReason(t) {
  if (!t) return null;
  if (t.length < 100) return null;
  if ((t.match(ZALGO_RE) || []).length >= 60) return { kind: "pattern", reason: "karakter bertumpuk (zalgo)" };
  if ((t.match(INVIS_RE) || []).length >= 100) return { kind: "pattern", reason: "karakter tak terlihat" };
  if (t.length >= 1000) {
    const cnt = new Map();
    for (const ch of t) if (!/\s/.test(ch)) cnt.set(ch, (cnt.get(ch) || 0) + 1);
    let top = 0; for (const v of cnt.values()) if (v > top) top = v;
    if (top / t.length >= 0.7) return { kind: "pattern", reason: "karakter berulang" };
  }
  if (t.length >= 6000) return { kind: "length", reason: "teks sangat panjang" };
  return null;
}
const modNoticeAt = new Map();
async function addWarn(sock, jid, sender, senderNum, why, adm) {
  const key = jid + "|" + senderNum;
  const n = (db.warns[key] || 0) + 1;
  if (n >= 3) {
    delete db.warns[key]; saveDB();
    await sock.sendMessage(jid, { text: adm ? `🚫 @${senderNum} mencapai 3 peringatan (${why}) dan dikeluarkan.` : `🚫 @${senderNum} mencapai 3 peringatan (${why}). Bot bukan admin, jadi tidak bisa mengeluarkan.`, mentions: [sender] });
    if (adm) { try { await sock.groupParticipantsUpdate(jid, [sender], "remove"); } catch {} }
    return;
  }
  db.warns[key] = n; saveDB();
  await sock.sendMessage(jid, { text: `⚠️ @${senderNum} ${why}.\nPeringatan *${n}/3*.`, mentions: [sender] });
}
async function moderateVirtex(sock, msg, jid, sender, senderNum, v) {
  let meta; try { meta = await groupMetaCached(sock, jid); } catch { return false; }
  if (isParticipantAdmin(meta, senderNum)) return false; // admin tidak disentuh
  const adm = botIsAdmin(sock, meta);
  if (!adm) {
    if (Date.now() - (modNoticeAt.get(jid) || 0) > 60000) {
      modNoticeAt.set(jid, Date.now());
      await sock.sendMessage(jid, { text: `🛡️ *Anti-virtex*: pesan mencurigakan dari @${senderNum} (${v.reason}). Jadikan bot admin supaya bisa menghapusnya.`, mentions: [sender] });
    }
    return true;
  }
  await modDelete(sock, jid, msg);
  if (v.kind === "pattern") {
    await sock.sendMessage(jid, { text: `🛡️ *Anti-virtex*\nPesan @${senderNum} dihapus (${v.reason}) dan pengirim dikeluarkan.`, mentions: [sender] });
    try { await sock.groupParticipantsUpdate(jid, [sender], "remove"); } catch {}
  } else {
    await addWarn(sock, jid, sender, senderNum, `mengirim ${v.reason}, pesan dihapus`, true);
  }
  return true;
}

const TOXIC_DEFAULT = ["anjing", "anjg", "bangsat", "bajingan", "kontol", "kntl", "memek", "ngentot", "entot", "jancok", "jancuk", "asu", "goblok", "tolol", "kampret", "pepek", "puki", "pukimak", "brengsek", "bgsd", "bgst", "kimak", "cukimai", "bedebah", "babi"];
const LEET = { "4": "a", "3": "e", "1": "i", "0": "o", "5": "s", "7": "t", "@": "a", "$": "s", "!": "i" };
const toxKey = (w) => String(w || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z]/g, "").replace(/([a-z])\1+/g, "$1");
const TOXIC_SET = new Set(TOXIC_DEFAULT.map(toxKey));
/** Cocokkan per kata utuh (bukan sebagian kata): tahan huruf berulang (anjiiing), angka (k0nt0l), dan akhiran -nya/-lah. */
function toxicHit(text, custom = []) {
  const extra = custom && custom.length ? new Set(custom) : null;
  const toks = String(text).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").split(/[\s.,;:?()"'`~^*_+=<>\/\\|{}\[\]-]+/).filter(Boolean);
  for (const t of toks) {
    if (t.length > 40) continue;
    for (const v0 of [t.replace(/[431057@$!]/g, (c) => LEET[c]), t]) {
      const v = v0.replace(/[^a-z]/g, "").replace(/([a-z])\1+/g, "$1");
      for (const cand of [v, v.replace(/(nya|lah|kah|pun)$/, "")]) {
        if (cand.length >= 3 && (TOXIC_SET.has(cand) || (extra && extra.has(cand)))) return cand;
      }
    }
  }
  return null;
}
async function moderateToxic(sock, msg, jid, sender, senderNum) {
  let meta; try { meta = await groupMetaCached(sock, jid); } catch { return false; }
  if (isParticipantAdmin(meta, senderNum)) return false;
  const adm = botIsAdmin(sock, meta);
  if (adm) await modDelete(sock, jid, msg);
  await addWarn(sock, jid, sender, senderNum, "memakai kata kasar" + (adm ? ", pesan dihapus" : ""), adm);
  return true;
}

