const PROTECTED_CMDS = new Set(["fitur", "menu", "help", "owner", "ownermenu", "ping", "runtime", "diagnosa", "deviceinfo", "setkey", "off", "restart", "mode", "ban", "unban", "listban", "addlimit", "setlimit", "resetlimit", "addprem", "delprem", "listprem", "cekuser", "listuser", "block", "unblock", "cekmenfess", "fess", "listbug", "delbug", "bc", "bcgc", "join", "leave", "addowner", "delowner", "stats", "anticall"]);
let aliasCache = null;
/** Baca daftar perintah dari kode sendiri: label "case" berurutan dihitung sebagai alias dari satu fitur. */
function getAliasGroups() {
  if (aliasCache) return aliasCache;
  const primary = new Map(), labels = new Map();
  try {
    let open = null;
    for (const line of fs.readFileSync(__filename, "utf8").split("\n")) {
      const mm = line.length < 400 && line.match(/^      case "([^"]+)":(.*)$/);
      if (!mm) { if (open && line.trim() && !line.trim().startsWith("//")) open = null; continue; } // baris isi perintah menutup grup alias
      if (!open) { open = mm[1]; labels.set(open, []); }
      labels.get(open).push(mm[1]); primary.set(mm[1], open);
      if (mm[2].trim() !== "") open = null; // label ini membuka isi perintah: grup selesai
    }
  } catch {}
  return (aliasCache = { primary, labels });
}

// ================= TEKS JADI PDF (huruf Helvetica bawaan PDF, tanpa library) =================
const PDF_HELV = [278,278,355,556,556,889,667,191,333,333,389,584,278,333,278,278,556,556,556,556,556,556,556,556,556,556,278,278,584,584,584,556,1015,667,667,722,722,667,611,778,722,278,500,667,556,833,722,778,667,778,722,667,611,722,667,944,667,667,611,278,278,278,469,556,333,556,556,500,556,556,278,556,556,222,222,500,222,833,556,556,556,556,333,500,278,556,500,722,500,500,500,334,260,334,584,761,556,556,222,556,333,1000,556,556,333,1000,667,333,1000,556,611,556,556,222,222,333,333,350,556,1000,333,1000,500,333,944,556,500,667,278,333,556,556,556,556,260,556,333,737,370,556,584,333,737,333,400,584,333,333,333,556,537,278,333,333,365,556,834,834,834,611,667,667,667,667,667,667,1000,722,667,667,667,667,278,278,278,278,722,722,778,778,778,778,778,584,778,722,722,722,722,667,667,611,556,556,556,556,556,556,889,500,556,556,556,556,278,278,278,278,556,556,556,556,556,556,556,584,611,556,556,556,556,500,556,500];
const CP1252 = { 0x20ac: 0x80, 0x201a: 0x82, 0x0192: 0x83, 0x201e: 0x84, 0x2026: 0x85, 0x2020: 0x86, 0x2021: 0x87, 0x02c6: 0x88, 0x2030: 0x89, 0x0160: 0x8a, 0x2039: 0x8b, 0x0152: 0x8c, 0x017d: 0x8e, 0x2018: 0x91, 0x2019: 0x92, 0x201c: 0x93, 0x201d: 0x94, 0x2022: 0x95, 0x2013: 0x96, 0x2014: 0x97, 0x02dc: 0x98, 0x2122: 0x99, 0x0161: 0x9a, 0x203a: 0x9b, 0x0153: 0x9c, 0x017e: 0x9e, 0x0178: 0x9f };
/** teks -> string cp1252 (satu karakter = satu kode). Karakter di luar cp1252 (emoji, huruf non-Latin) jadi "?". */
function toCp1252(text) {
  let out = "", unsupported = 0;
  for (const ch of String(text).replace(/\r\n?/g, "\n")) {
    let c = ch.codePointAt(0);
    if (c === 10) { out += "\n"; continue; }
    if (c === 9) { out += "    "; continue; }
    if (c === 0xa0) c = 32;
    if (c < 32 || c === 127 || (c >= 0x80 && c <= 0x9f)) continue;
    if ((c >= 0xfe00 && c <= 0xfe0f) || (c >= 0x200b && c <= 0x200f) || (c >= 0x202a && c <= 0x202e) || c === 0x2060 || c === 0xfeff) continue;
    if (c < 128 || (c >= 0xa0 && c <= 0xff)) out += String.fromCharCode(c);
    else if (CP1252[c] !== undefined) out += String.fromCharCode(CP1252[c]);
    else { out += "?"; unsupported++; }
  }
  return { str: out, unsupported };
}
const helvW = (s, size) => { let t = 0; for (let i = 0; i < s.length; i++) t += PDF_HELV[s.charCodeAt(i) - 32] ?? 556; return (t * size) / 1000; };
function wrapPdfLine(line, maxW, size) {
  if (!line.trim()) return [""];
  const ind = " ".repeat(Math.min(line.match(/^ */)[0].length, 16));
  const lines = []; let cur = ind;
  for (const word of line.trim().split(/ +/)) {
    const cand = cur === ind ? ind + word : cur + " " + word;
    if (helvW(cand, size) <= maxW) { cur = cand; continue; }
    if (cur !== ind) lines.push(cur);
    cur = ind + word;
    while (helvW(cur, size) > maxW) { // kata lebih panjang dari satu baris: potong per huruf
      let k = cur.length;
      while (k > ind.length + 1 && helvW(cur.slice(0, k), size) > maxW) k--;
      lines.push(cur.slice(0, k));
      cur = ind + cur.slice(k);
    }
  }
  if (cur.trim() || !lines.length) lines.push(cur);
  return lines;
}
const pdfEsc = (s) => s.replace(/[\\()]/g, (c) => "\\" + c).replace(/[\x80-\xff]/g, (c) => "\\" + c.charCodeAt(0).toString(8));
function buildTextPdf(text) {
  const { str, unsupported } = toCp1252(text);
  const SIZE = 11, LEAD = 15, ML = 56, PW = 595, PH = 842, TOP = 64, BOT = 64;
  const perPage = Math.floor((PH - TOP - BOT) / LEAD);
  const lines = [];
  for (const raw of str.split("\n")) lines.push(...wrapPdfLine(raw.replace(/\s+$/, ""), PW - 2 * ML, SIZE));
  while (lines.length && lines[lines.length - 1] === "") lines.pop();
  const pages = [];
  for (let i = 0; i < lines.length; i += perPage) pages.push(lines.slice(i, i + perPage));
  if (!pages.length) pages.push([""]);
  const chunks = []; let len = 0; const offs = [];
  const push = (s) => { const b = Buffer.from(s, "latin1"); chunks.push(b); len += b.length; };
  const obj = (n, body) => { offs[n] = len; push(`${n} 0 obj\n${body}\nendobj\n`); };
  push("%PDF-1.4\n%\xE2\xE3\xCF\xD3\n");
  obj(1, "<< /Type /Catalog /Pages 2 0 R >>");
  obj(2, `<< /Type /Pages /Kids [${pages.map((_, i) => `${4 + 2 * i} 0 R`).join(" ")}] /Count ${pages.length} >>`);
  obj(3, "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>");
  pages.forEach((pl, i) => {
    let c = `BT /F1 ${SIZE} Tf ${LEAD} TL ${ML} ${PH - TOP - SIZE} Td\n`;
    pl.forEach((l, j) => { c += (j ? "T*" : "") + (l ? ` (${pdfEsc(l)}) Tj\n` : "\n"); });
    c += `ET\nBT /F1 8 Tf 0.5 g ${ML} 30 Td (ZYNORA - Halaman ${i + 1}/${pages.length}) Tj ET`;
    obj(4 + 2 * i, `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${PW} ${PH}] /Resources << /Font << /F1 3 0 R >> >> /Contents ${5 + 2 * i} 0 R >>`);
    obj(5 + 2 * i, `<< /Length ${Buffer.byteLength(c, "latin1")} >>\nstream\n${c}\nendstream`);
  });
  const total = 3 + 2 * pages.length, xref = len;
  let x = `xref\n0 ${total + 1}\n0000000000 65535 f \n`;
  for (let n = 1; n <= total; n++) x += String(offs[n]).padStart(10, "0") + " 00000 n \n";
  push(x + `trailer\n<< /Size ${total + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`);
  return { pdf: Buffer.concat(chunks), pages: pages.length, unsupported };
}

