// ----- Nama pembuat stiker (EXIF WebP, tanpa library) -----
function webpWithExif(buf, pack, author) {
  if (buf.length < 20 || buf.toString("ascii", 0, 4) !== "RIFF" || buf.toString("ascii", 8, 12) !== "WEBP") throw new Error("ini bukan stiker WebP");
  const json = Buffer.from(JSON.stringify({ "sticker-pack-id": "zynora." + Date.now().toString(36), "sticker-pack-name": pack, "sticker-pack-publisher": author, emojis: [""] }), "utf8");
  const hdr = Buffer.from([0x49, 0x49, 0x2a, 0x00, 0x08, 0x00, 0x00, 0x00, 0x01, 0x00, 0x41, 0x57, 0x07, 0x00, 0x00, 0x00, 0x00, 0x00, 0x16, 0x00, 0x00, 0x00]);
  hdr.writeUInt32LE(json.length, 14);
  const exif = Buffer.concat([hdr, json]);
  const chunks = [];
  for (let pos = 12; pos + 8 <= buf.length;) {
    const tag = buf.toString("ascii", pos, pos + 4), sz = buf.readUInt32LE(pos + 4);
    chunks.push({ tag, data: Buffer.from(buf.subarray(pos + 8, pos + 8 + sz)) });
    pos += 8 + sz + (sz & 1);
  }
  let vp8x = chunks.find((c) => c.tag === "VP8X");
  if (!vp8x) {
    const img = chunks.find((c) => c.tag === "VP8 " || c.tag === "VP8L");
    if (!img) throw new Error("struktur WebP tidak dikenali");
    let w, h, alpha = chunks.some((c) => c.tag === "ALPH") ? 1 : 0;
    if (img.tag === "VP8 ") { w = img.data.readUInt16LE(6) & 0x3fff; h = img.data.readUInt16LE(8) & 0x3fff; }
    else { const bits = img.data.readUInt32LE(1); w = (bits & 0x3fff) + 1; h = ((bits >> 14) & 0x3fff) + 1; alpha = (bits >> 28) & 1; }
    const d = Buffer.alloc(10); d[0] = alpha ? 0x10 : 0; d.writeUIntLE(w - 1, 4, 3); d.writeUIntLE(h - 1, 7, 3);
    vp8x = { tag: "VP8X", data: d }; chunks.unshift(vp8x);
  }
  vp8x.data[0] |= 0x08; // bendera EXIF
  const kept = chunks.filter((c) => c.tag !== "EXIF"); kept.push({ tag: "EXIF", data: exif });
  const parts = kept.map((c) => { const h = Buffer.alloc(8); h.write(c.tag, 0, "ascii"); h.writeUInt32LE(c.data.length, 4); return Buffer.concat([h, c.data, c.data.length & 1 ? Buffer.alloc(1) : Buffer.alloc(0)]); });
  const body = Buffer.concat([Buffer.from("WEBP"), ...parts]);
  const riff = Buffer.alloc(8); riff.write("RIFF", 0, "ascii"); riff.writeUInt32LE(body.length, 4);
  return Buffer.concat([riff, body]);
}

// ----- Kalender bulanan -----
function calendarText(y, m, todayStr) {
  const first = new Date(Date.UTC(y, m - 1, 1, 12)), days = new Date(Date.UTC(y, m, 0)).getUTCDate();
  let t = "Min Sen Sel Rab Kam Jum Sab \n", line = "    ".repeat(first.getUTCDay());
  for (let d = 1; d <= days; d++) {
    const isToday = todayStr === `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
    line += isToday ? `[${String(d).padStart(2)}]` : ` ${String(d).padStart(2)} `;
    if ((first.getUTCDay() + d) % 7 === 0) { t += line + "\n"; line = ""; }
  }
  if (line) t += line + "\n";
  return t;
}

// ----- Anti-call, sambutan/perpisahan, jadwal pesan, laporan error -----
const callSeen = new Map();
const isOwnerNum = (n) => !!n && (n === OWNER || (settings.owners || []).includes(n));
async function handleCall(sock, calls) {
  if (!settings.anticall) return;
  for (const c of calls || []) {
    if (c.status !== "offer") continue;
    const num = numOf(c.callerPn || c.from || "");
    if (isOwnerNum(num) || isOwnerNum(numOf(c.from || ""))) continue;
    try { await sock.rejectCall(c.id, c.from); } catch {}
    if (Date.now() - (callSeen.get(c.from) || 0) > 10 * 60 * 1000) {
      callSeen.set(c.from, Date.now());
      await sock.sendMessage(c.from, { text: "📵 *Bot tidak menerima panggilan.*\nSilakan kirim pesan teks. Ketik *.menu* untuk melihat fitur." }).catch(() => {});
    }
  }
}
const fillTpl = (tpl, v) => String(tpl).replace(/@user|\{user\}/gi, `@${v.num}`).replace(/\{grup\}|\{group\}/gi, () => v.group).replace(/\{jumlah\}/gi, String(v.count));
const DEFAULT_BYE = "👋 Selamat tinggal @user, sampai jumpa lagi!";
async function handleParticipants(sock, id, participants, action) {
  try {
    const wel = action === "add" && settings.welcome[id], bye = action === "remove" && settings.goodbyeMsg[id];
    if (!wel && !bye) return;
    const meta = await sock.groupMetadata(id);
    for (const p of participants) {
      const jid = typeof p === "string" ? p : p.id;
      const v = { num: numOf(jid), group: meta.subject, count: meta.participants.length };
      let text;
      if (wel) {
        text = settings.welcomeMsg[id] ? fillTpl(settings.welcomeMsg[id], v) : `👋 Selamat datang @${v.num} di *${v.group}*!\nKetik *.menu* untuk lihat fitur bot.`;
        if (settings.rules[id]) text += `\n\n📜 *Aturan grup:*\n${settings.rules[id]}`;
      } else text = fillTpl(settings.goodbyeMsg[id], v);
      await sock.sendMessage(id, { text, mentions: [jid] });
    }
  } catch {}
}
const DAY_IDX = { minggu: 0, senin: 1, selasa: 2, rabu: 3, kamis: 4, jumat: 5, sabtu: 6 };
function wibParts(ms) {
  const p = {};
  for (const x of new Intl.DateTimeFormat("en-GB", { timeZone: "Asia/Jakarta", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hour12: false, weekday: "short" }).formatToParts(new Date(ms))) p[x.type] = x.value;
  const hh = p.hour === "24" ? 0 : +p.hour;
  return { date: `${p.year}-${p.month}-${p.day}`, min: hh * 60 + +p.minute, wd: ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].indexOf(p.weekday) };
}
/** Kirim pesan terjadwal yang waktunya tiba (toleransi telat 10 menit, 1x per hari per jadwal). */
async function scheduleTick(now = Date.now()) {
  const sock = getSock();
  if (!sock || !settings.schedules.length) return 0;
  const t = wibParts(now); let n = 0;
  for (const s of settings.schedules.slice()) {
    const [h, mi] = s.time.split(":").map(Number), diff = t.min - (h * 60 + mi);
    if (diff < 0 || diff > 10 || s.last === t.date) continue;
    if (s.day !== "harian" && s.day !== t.wd) continue;
    s.last = t.date; saveSettings();
    try { await sock.sendMessage(s.jid, { text: s.text }); n++; } catch {}
  }
  return n;
}
setInterval(() => { scheduleTick().catch(() => {}); }, 30000).unref();
const errStat = new Map();
/** 3 error pada fitur yang sama dalam 10 menit -> peringatan ke owner (maks. 1x per 30 menit per fitur). */
function noteError(sock, cmd, e) {
  const now = Date.now(), s = errStat.get(cmd) || { n: 0, t0: now, alertAt: 0 };
  if (now - s.t0 > 10 * 60 * 1000) { s.n = 0; s.t0 = now; }
  s.n++; errStat.set(cmd, s);
  if (s.n < 3 || now - s.alertAt < 30 * 60 * 1000) return false;
  s.alertAt = now; s.n = 0; s.t0 = now;
  const target = [...(settings.owners || []), OWNER].find((x) => /^\d{8,15}$/.test(String(x)));
  if (!target) return false;
  sock.sendMessage(`${target}@s.whatsapp.net`, { text: `⚠️ *Peringatan fitur*\n*.${cmd}* gagal 3x dalam 10 menit.\nError terakhir: ${String(e?.message || e).slice(0, 200)}\n\nMatikan sementara: *.fitur off ${cmd}*` }).catch(() => {});
  return true;
}

// ================= .clear: bersihkan chat (fitur "Clear chat" bawaan WhatsApp) =================
function baileysMajor() {
  try {
    const dir = path.dirname(require.resolve("@whiskeysockets/baileys"));
    for (const p of [path.join(dir, "package.json"), path.join(dir, "..", "package.json")]) {
      try { const v = JSON.parse(fs.readFileSync(p, "utf8")); if (/baileys/i.test(String(v.name))) return parseInt(String(v.version), 10); } catch {}
    }
  } catch {}
  return NaN;
}
/** Baileys 7+: clear chat. Baileys 6.x tidak punya clear-seluruh-chat, jadi dipakai delete chat. Hanya bentuk yang tidak dikenal (TypeError) dicoba dengan bentuk lain. */
async function clearChat(sock, jid, last) {
  const modern = { clear: true, lastMessages: [last] }, legacy = { delete: true, lastMessages: [last] };
  const order = baileysMajor() < 7 ? [legacy, modern] : [modern, legacy];
  let err;
  for (const mod of order) {
    try { await sock.chatModify(mod, jid); return mod === modern ? "clear" : "delete"; }
    catch (e) { err = e; if (!(e instanceof TypeError)) throw e; }
  }
  throw err;
}

// ================= DATA ACAK: tidak mengulang sebelum semua habis =================
const bagState = new Map();
/** Ambil satu item acak dari arr; item tidak diulang sampai seluruh isi arr sudah keluar (per kunci, mis. per chat). */
function pickBag(key, arr) {
  let s = bagState.get(key);
  if (!s || !s.bag.length) {
    const bag = arr.map((_, i) => i);
    for (let i = bag.length - 1; i > 0; i--) { const j = require("crypto").randomInt(i + 1); [bag[i], bag[j]] = [bag[j], bag[i]]; }
    if (s && bag.length > 1 && bag[bag.length - 1] === s.last) [bag[0], bag[bag.length - 1]] = [bag[bag.length - 1], bag[0]]; // putaran baru tidak dimulai dengan item terakhir tadi
    s = { bag, last: s ? s.last : -1 };
    bagState.set(key, s);
  }
  s.last = s.bag.pop();
  return arr[s.last];
}

// ================= KOMPRES & TOPDF =================
const fmtSize = (n) => (n >= 1048576 ? (n / 1048576).toFixed(1).replace(".", ",") + " MB" : Math.max(1, Math.round(n / 1024)) + " KB");
const COMPRESS_IMG = { 1: { max: 2048, q: 4 }, 2: { max: 1440, q: 8 }, 3: { max: 1080, q: 13 } };
const COMPRESS_VID = { 1: { side: 1080, crf: 26, ab: "128k" }, 2: { side: 720, crf: 29, ab: "96k" }, 3: { side: 480, crf: 33, ab: "64k" } };
const jpgFilter = (max) => `scale=w='min(${max},iw)':h='min(${max},ih)':force_original_aspect_ratio=decrease`;
async function compressImage(buf, lvl) {
  const o = COMPRESS_IMG[lvl], inp = tmpFile("img"), out = tmpFile("jpg");
  try {
    fs.writeFileSync(inp, buf);
    await run("ffmpeg", ["-y", "-i", inp, "-vf", jpgFilter(o.max), "-frames:v", "1", "-q:v", String(o.q), "-pix_fmt", "yuvj420p", out]);
    return fs.readFileSync(out);
  } finally { cleanup(inp, out); }
}
async function compressVideo(buf, lvl) {
  const o = COMPRESS_VID[lvl], inp = tmpFile("mp4"), out = tmpFile("mp4");
  try {
    fs.writeFileSync(inp, buf);
    const vf = `scale=w='if(lt(iw,ih),min(${o.side},iw),-2)':h='if(lt(iw,ih),-2,min(${o.side},ih))',scale=trunc(iw/2)*2:trunc(ih/2)*2`;
    await run("ffmpeg", ["-y", "-i", inp, "-vf", vf, "-c:v", "libx264", "-preset", "veryfast", "-crf", String(o.crf), "-pix_fmt", "yuv420p", "-movflags", "+faststart", "-c:a", "aac", "-b:a", o.ab, out], { timeout: 420000 });
    return fs.readFileSync(out);
  } finally { cleanup(inp, out); }
}

/** Tulis PDF langsung (tanpa library): tiap foto JPEG satu halaman A4 (otomatis tegak/mendatar). */
function buildPdf(pages) {
  const chunks = []; let len = 0; const offs = [];
  const push = (b) => { const buf = Buffer.isBuffer(b) ? b : Buffer.from(b, "latin1"); chunks.push(buf); len += buf.length; };
  const obj = (n, body) => { offs[n] = len; push(`${n} 0 obj\n${body}\nendobj\n`); };
  push("%PDF-1.4\n%\xE2\xE3\xCF\xD3\n");
  obj(1, "<< /Type /Catalog /Pages 2 0 R >>");
  obj(2, `<< /Type /Pages /Kids [${pages.map((_, i) => `${3 + 3 * i} 0 R`).join(" ")}] /Count ${pages.length} >>`);
  pages.forEach((p, i) => {
    const land = p.w > p.h, PW = land ? 842 : 595, PH = land ? 595 : 842, M = 24;
    const sc = Math.min((PW - 2 * M) / p.w, (PH - 2 * M) / p.h);
    const dw = +(p.w * sc).toFixed(2), dh = +(p.h * sc).toFixed(2), x = +((PW - dw) / 2).toFixed(2), y = +((PH - dh) / 2).toFixed(2);
    const content = `q ${dw} 0 0 ${dh} ${x} ${y} cm /Im0 Do Q`;
    obj(3 + 3 * i, `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${PW} ${PH}] /Resources << /XObject << /Im0 ${5 + 3 * i} 0 R >> >> /Contents ${4 + 3 * i} 0 R >>`);
    obj(4 + 3 * i, `<< /Length ${content.length} >>\nstream\n${content}\nendstream`);
    offs[5 + 3 * i] = len;
    push(`${5 + 3 * i} 0 obj\n<< /Type /XObject /Subtype /Image /Width ${p.w} /Height ${p.h} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${p.jpg.length} >>\nstream\n`);
    push(p.jpg); push("\nendstream\nendobj\n");
  });
  const total = 2 + 3 * pages.length, xref = len;
  let x = `xref\n0 ${total + 1}\n0000000000 65535 f \n`;
  for (let n = 1; n <= total; n++) x += String(offs[n]).padStart(10, "0") + " 00000 n \n";
  push(x + `trailer\n<< /Size ${total + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`);
  return Buffer.concat(chunks);
}
const pdfFromItems = (items) => buildPdf(items.map((it) => ({ jpg: fs.readFileSync(it.file), w: it.w, h: it.h })));
const pdfName = () => "ZYNORA-" + new Intl.DateTimeFormat("sv-SE", { timeZone: "Asia/Jakarta", dateStyle: "short", timeStyle: "short" }).format(new Date(Date.now())).replace(/[-: ]/g, "").replace(/^(\d{8})(\d{4})$/, "$1-$2") + ".pdf";

