function pdfOpen(key, jid) {
  pdfClose(key);
  const s = { key, files: [], pending: new Set(), timer: null, fullWarned: false };
  s.touch = () => {
    clearTimeout(s.timer);
    s.timer = setTimeout(() => {
      if (pdfSessions.get(key) !== s) return;
      const n = s.files.length;
      pdfClose(key);
      getSock()?.sendMessage(jid, { text: `⌛ Sesi *.topdf* berakhir (10 menit tanpa aktivitas)${n ? `, ${n} foto dibuang` : ""}.` }).catch(() => {});
    }, PDF_TTL);
  };
  s.touch();
  pdfSessions.set(key, s);
  return s;
}
/** Tambah satu foto ke sesi; urutan mengikuti urutan kedatangan walau diproses bersamaan. */
async function pdfAdd(sock, msg, s, media) {
  const jid = msg.key.remoteJid;
  if (s.files.length >= PDF_MAX) {
    if (!s.fullWarned) { s.fullWarned = true; await sock.sendMessage(jid, { text: `Maksimal ${PDF_MAX} foto. Ketik *.topdf selesai* untuk membuat PDF.` }, { quoted: msg }); }
    return;
  }
  const slot = { file: null, w: 0, h: 0 };
  s.files.push(slot);
  const p = (async () => {
    try { Object.assign(slot, await pdfPrepare(await download(media))); }
    catch (e) { const i = s.files.indexOf(slot); if (i >= 0) s.files.splice(i, 1); throw e; }
  })();
  s.pending.add(p);
  p.then(() => {}, () => {}).then(() => s.pending.delete(p));
  try { await p; }
  catch (e) { await sock.sendMessage(jid, { text: `⚠️ Foto itu gagal dibaca (${String(e.message).slice(0, 80)}). Kirim ulang fotonya.` }, { quoted: msg }); return; }
  if (pdfSessions.get(s.key) !== s) { cleanup(slot.file); return; }
  s.touch();
  sock.sendMessage(jid, { react: { text: "📄", key: msg.key } }).catch(() => {});
}
async function pdfCollect(sock, msg, jid, senderNum) {
  const s = pdfSessions.get(`${jid}|${senderNum}`);
  const m = unwrap(msg.message) || {};
  if (!s || !m.imageMessage) return false;
  await pdfAdd(sock, msg, s, { type: "image", content: m.imageMessage });
  return true;
}

// ================= KALENDER: umur, zodiak, hijriah, Ramadhan (hitungan lokal, tanpa API) =================
const MONTHS_ID = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
const DAYS_ID = ["Minggu", "Senin", "Selasa", "Rabu", "Kamis", "Jumat", "Sabtu"];
const HIJRI_MONTHS = ["Muharram", "Safar", "Rabiul Awal", "Rabiul Akhir", "Jumadil Awal", "Jumadil Akhir", "Rajab", "Syaban", "Ramadhan", "Syawal", "Dzulqadah", "Dzulhijjah"];
const PASARAN = ["Legi", "Pahing", "Pon", "Wage", "Kliwon"];
const MS_DAY = 864e5;
const utcDay = (y, m, d) => Date.UTC(y, m - 1, d, 12); // tengah hari UTC: aman dari pergeseran zona waktu
const msToParts = (ms) => { const t = new Date(ms); return { y: t.getUTCFullYear(), m: t.getUTCMonth() + 1, d: t.getUTCDate() }; };
const dateID = (ms) => { const t = new Date(ms); return `${DAYS_ID[t.getUTCDay()]}, ${t.getUTCDate()} ${MONTHS_ID[t.getUTCMonth()]} ${t.getUTCFullYear()}`; };
const todayMs = () => {
  const [y, m, d] = new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Jakarta", year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date(Date.now())).split("-").map(Number);
  return utcDay(y, m, d);
};
const validYMD = (y, m, d) => { const t = new Date(Date.UTC(y, m - 1, d, 12)); return t.getUTCFullYear() === y && t.getUTCMonth() === m - 1 && t.getUTCDate() === d; };
const MONTH_ALIAS = { ags: 7, agt: 7, agst: 7, des: 11, dec: 11, okt: 9, oct: 9, mei: 4, may: 4 };
const monthIdx = (t) => {
  if (t.length < 3) return -1;
  if (MONTH_ALIAS[t] !== undefined) return MONTH_ALIAS[t];
  return MONTHS_ID.findIndex((n) => n.toLowerCase().startsWith(t));
};
/** "17-08-2000", "17/8/2000", "17 8 2000", "17082000", "17 agustus 2000", "17 agu" -> {d, m, y|null} atau null */
function parseDateInput(str) {
  let s = String(str || "").toLowerCase().replace(/[\/.,\-]+/g, " ").trim();
  if (/^\d{8}$/.test(s)) s = `${s.slice(0, 2)} ${s.slice(2, 4)} ${s.slice(4)}`;
  const tok = s.split(/\s+/).filter(Boolean);
  if (!tok.length || tok.length > 3) return null;
  let m = null; const nums = [];
  for (const t of tok) {
    if (/^\d+$/.test(t)) nums.push(+t);
    else { const i = monthIdx(t); if (i < 0 || m !== null) return null; m = i + 1; }
  }
  let d, y = null;
  if (m !== null) { if (nums.length < 1 || nums.length > 2) return null; [d, y = null] = nums; }
  else { if (nums.length < 2) return null; [d, m, y = null] = nums; }
  if (!(d >= 1 && d <= 31 && m >= 1 && m <= 12)) return null;
  if (y !== null && !((y >= 1900 && y <= 2100) || (y >= 1320 && y <= 1520))) return null;
  return { d, m, y };
}

