    medan: "Asia/Jakarta", palembang: "Asia/Jakarta", padang: "Asia/Jakarta", pekanbaru: "Asia/Jakarta", batam: "Asia/Jakarta", aceh: "Asia/Jakarta",
    lampung: "Asia/Jakarta", pontianak: "Asia/Pontianak", palangkaraya: "Asia/Pontianak", jambi: "Asia/Jakarta", bengkulu: "Asia/Jakarta",
    denpasar: "Asia/Makassar", bali: "Asia/Makassar", makassar: "Asia/Makassar", manado: "Asia/Makassar", balikpapan: "Asia/Makassar",
