    ambon: "Asia/Jayapura", jayapura: "Asia/Jayapura", sorong: "Asia/Jayapura", merauke: "Asia/Jayapura", ternate: "Asia/Jayapura",
    singapura: "Asia/Singapore", singapore: "Asia/Singapore", "kuala lumpur": "Asia/Kuala_Lumpur", malaysia: "Asia/Kuala_Lumpur", bangkok: "Asia/Bangkok",
    hanoi: "Asia/Ho_Chi_Minh", manila: "Asia/Manila", "hong kong": "Asia/Hong_Kong", taipei: "Asia/Taipei", beijing: "Asia/Shanghai", shanghai: "Asia/Shanghai",
