    massa: [["mg", 1e-6, ["mg", "miligram"]], ["g", 0.001, ["g", "gr", "gram"]], ["kg", 1, ["kg", "kilogram"]], ["ons", 0.1, ["ons"]], ["kwintal", 100, ["kwintal", "kw"]], ["ton", 1000, ["ton"]], ["oz", 0.028349523125, ["oz", "ounce"]], ["lb", 0.45359237, ["lb", "lbs", "pon", "pound"]]],
    volume: [["ml", 0.001, ["ml", "mililiter"]], ["liter", 1, ["l", "lt", "liter", "litre"]], ["m³", 1000, ["m3", "kubik"]], ["galon (AS)", 3.785411784, ["gal", "galon", "gallon"]], ["cangkir (AS)", 0.2365882365, ["cup", "cangkir"]], ["sdt", 0.00492892159, ["tsp", "sdt"]], ["sdm", 0.01478676478, ["tbsp", "sdm"]], ["fl oz", 0.0295735296, ["floz"]]],
