  const CAT_OUT = [
    ["Makan & Minum", /makan|minum|kopi|bakso|nasi|jajan|snack|resto|cafe|kafe|gofood|grabfood|shopeefood|sarapan|ayam|mie|boba|es\b/],
    ["Transport", /bensin|pertalite|pertamax|ojek|grab|gojek|parkir|tol\b|bus\b|kereta|krl|angkot|transport|ojol|servis motor|bengkel/],
    ["Tagihan", /listrik|pulsa|internet|wifi|pln|pdam|kos\b|kost|kontrakan|sewa|cicilan|token|paket data|bpjs|asuransi|tagihan/],
    ["Belanja", /belanja|beli|shopee|tokped|tokopedia|baju|lazada|sepatu|skincare|indomaret|alfamart/],
    ["Kesehatan", /obat|dokter|\brs\b|apotek|klinik|vitamin/],
    ["Hiburan", /nonton|game|netflix|spotify|bioskop|topup|top up|diamond|konser|liburan|wisata/],
    ["Pendidikan", /buku|kuliah|spp|kursus|les\b|ukt|seminar/],
    ["Sedekah & Zakat", /sedekah|zakat|infaq|donasi|amal/],
  ];
  const CAT_IN = [
    ["Gaji", /gaji|salary/],
    ["Bonus & THR", /bonus|thr\b/],
    ["Penjualan", /jual|dagang|omzet|untung|laba/],
  ];
  const INCOME_WORDS = /\b(gaji|terima|diterima|masuk|bonus|thr|dapat|transferan|dikirim|untung|laba|jual|cashback|komisi|salary)\b/i;
  const guessCat = (ket, income) => {
    const k = String(ket || "").toLowerCase();
    for (const [name, re] of income ? CAT_IN : CAT_OUT) if (re.test(k)) return name;
    return income ? "Pemasukan lain" : "Lainnya";
  };
  const myEntries = (num) => { const z = store(); z.uang = z.uang || {}; return (z.uang[num] = z.uang[num] || []); };

  async function cmdCatatUang(ctx) {
    const { args, reply, senderNum } = ctx;
    const usage = `💰 *Catat Uang*\nFormat: *.catatuang <+/-jumlah> <keterangan>*\n\nContoh:\n*.catatuang -25rb makan siang*\n*.catatuang +5jt gaji*\n*.catatuang 1,5jt bayar kos*\n\nPerintah lain:\n*.catatuang list* → 10 catatan terakhir\n*.catatuang hapus <ID>*\n*.laporanuang* → rekap bulan ini\n_Tanpa tanda +/-, bot menebak dari kata (gaji, terima = masuk; lainnya = keluar)._`;
    const a = args.trim();
    if (!a) return reply(usage);
    const list = myEntries(senderNum);
    if (/^list\b/i.test(a)) {
      if (!list.length) return reply("Belum ada catatan. Contoh: *.catatuang -25rb makan siang*");
      return reply("🧾 *Catatan terakhir*\n" + list.slice(-10).reverse().map((e) => `#${e.id} ${e.amt >= 0 ? "➕" : "➖"} ${rp(Math.abs(e.amt))} • ${e.cat}${e.ket ? " • " + e.ket : ""} (${e.d.slice(5)})`).join("\n"));
    }
    const del = a.match(/^(?:hapus|del)\s+#?(\d+)$/i);
    if (del) {
      const i = list.findIndex((e) => e.id === +del[1]);
      if (i < 0) return reply(`Catatan #${del[1]} tidak ditemukan. Lihat ID di *.catatuang list*`);
      const [e] = list.splice(i, 1); env.saveDB();
      return reply(`🗑️ Catatan #${e.id} (${rp(Math.abs(e.amt))} ${e.ket || e.cat}) dihapus.`);
    }
    const words = a.split(/\s+/);
    const idx = words.findIndex((w) => isAmountTok(w));
    if (idx < 0) return reply("Jumlah tidak terbaca.\n\n" + usage);
    const tok = words[idx];
    const val = parseRp(tok);
    if (!val || val <= 0) return reply("Jumlah harus lebih dari 0.\n\n" + usage);
    if (val > 1e12) return reply("Jumlah terlalu besar.");
    const ket = words.filter((_, i) => i !== idx).join(" ").trim().slice(0, 80);
    const income = tok.startsWith("+") ? true : tok.startsWith("-") ? false : INCOME_WORDS.test(ket);
    const e = { id: nextId("uang"), amt: income ? val : -val, cat: guessCat(ket, income), ket, d: wibDate(), ts: Date.now() };
    list.push(e);
    if (list.length > 3000) list.splice(0, list.length - 3000);
    env.saveDB();
    const ym = e.d.slice(0, 7);
    const bal = list.filter((x) => x.d.startsWith(ym)).reduce((s, x) => s + x.amt, 0);
    return reply(`${income ? "➕ *Pemasukan*" : "➖ *Pengeluaran*"} dicatat (#${e.id})\n${rp(val)} • ${e.cat}${ket ? "\n📝 " + ket : ""}\n\n🧮 Saldo ${monthLabel(ym)}: *${rp(bal)}*`);
  }

  async function cmdLaporanUang(ctx) {
    const { args, reply, senderNum } = ctx;
    const list = myEntries(senderNum);
    const a = args.trim().toLowerCase();
    if (/^hapus\s+semua$/.test(a)) { const n = list.length; list.length = 0; env.saveDB(); return reply(`🗑️ ${n} catatan keuanganmu dihapus.`); }
    if (a === "hapus") return reply("Menghapus *semua* catatan tidak bisa dibatalkan.\nKetik: *.laporanuang hapus semua*");
    const cur = wibDate().slice(0, 7);
    let ym = cur;
    if (/^(lalu|kemarin|bulan lalu)$/.test(a)) { let [y, m] = cur.split("-").map(Number); m--; if (!m) { m = 12; y--; } ym = `${y}-${String(m).padStart(2, "0")}`; }
    else if (/^\d{4}-\d{2}$/.test(a)) ym = a;
    else if (a && !/^(ini|bulan ini)$/.test(a)) return reply("Format: *.laporanuang* | *.laporanuang lalu* | *.laporanuang 2026-10* | *.laporanuang hapus semua*");
    const rows = list.filter((e) => e.d.startsWith(ym));
    if (!rows.length) return reply(`Belum ada catatan di ${monthLabel(ym)}.\nContoh: *.catatuang -25rb makan siang*`);
    const inc = rows.filter((e) => e.amt > 0).reduce((s, e) => s + e.amt, 0);
    const out = rows.filter((e) => e.amt < 0).reduce((s, e) => s - e.amt, 0);
    const byCat = new Map();
    for (const e of rows.filter((x) => x.amt < 0)) byCat.set(e.cat, (byCat.get(e.cat) || 0) - e.amt);
    const cats = [...byCat.entries()].sort((x, y) => y[1] - x[1]);
    let t = `📊 *Laporan Keuangan — ${monthLabel(ym)}*\n\n💰 Pemasukan: *${rp(inc)}*\n💸 Pengeluaran: *${rp(out)}*\n🧮 Saldo: *${rp(inc - out)}*\n`;
    if (cats.length) t += "\n*Pengeluaran per kategori*\n" + cats.map(([c, v]) => `${bar((v / out) * 100)} ${c}\n    ${rp(v)} (${Math.round((v / out) * 100)}%)`).join("\n") + "\n";
    t += `\n_${rows.length} transaksi • ${out > inc ? "⚠️ pengeluaran melebihi pemasukan" : "✅ aman"}_`;
    return reply(t);
  }

  // ===================== Hutang & tagih =====================
  const debts = () => { const z = store(); z.hutang = z.hutang || []; return z.hutang; };
  const mention = (jidOrNum) => "@" + env.numOf(jidOrNum);

  async function cmdHutang(ctx) {
    const { args, reply, senderNum, sock, jid, msg, target } = ctx;
    const usage = `🧾 *Catatan Hutang*\nFormat: *.hutang @tag <jumlah> [keterangan]*\n(atau reply pesannya lalu *.hutang <jumlah>*)\n\nContoh:\n*.hutang @Budi 50rb makan siang*\n\nPerintah lain:\n*.hutang list* → siapa saja yang berutang padamu\n*.hutang saya* → utangmu ke orang lain\n*.hutang lunas <ID>* atau *.hutang lunas @tag*\n*.hutang hapus <ID>*\n*.tagih* → kirim pengingat sopan`;
    const a = args.trim();
    if (!a) return reply(usage);
    const all = debts();
    if (/^(list|daftar)\b/i.test(a)) {
      const mine = all.filter((d) => d.kreditur === senderNum && !d.lunas);
      if (!mine.length) return reply("Tidak ada yang berutang padamu. 🎉");
      const by = new Map();
      for (const d of mine) { (by.get(d.debitur) || by.set(d.debitur, []).get(d.debitur)).push(d); }
      let total = 0, lines = [];
      for (const [num, arr] of by) {
        const sub = arr.reduce((s, d) => s + d.amt, 0); total += sub;
        lines.push(`👤 @${num} — *${rp(sub)}*\n` + arr.map((d) => `   #${d.id} ${rp(d.amt)}${d.ket ? " • " + d.ket : ""} (${d.d.slice(5)})`).join("\n"));
      }
      return sock.sendMessage(jid, { text: `🧾 *Yang berutang padamu*\n\n${lines.join("\n\n")}\n\n💰 Total: *${rp(total)}*`, mentions: [...by.keys()].map((n) => env.toJid(n)) }, { quoted: msg });
    }
    if (/^saya\b/i.test(a)) {
      const mine = all.filter((d) => d.debitur === senderNum && !d.lunas);
      if (!mine.length) return reply("Kamu tidak tercatat punya utang. 👍");
      const total = mine.reduce((s, d) => s + d.amt, 0);
      return sock.sendMessage(jid, { text: "🧾 *Utangmu*\n" + mine.map((d) => `#${d.id} ke @${d.kreditur} — ${rp(d.amt)}${d.ket ? " • " + d.ket : ""}`).join("\n") + `\n\n💰 Total: *${rp(total)}*`, mentions: mine.map((d) => env.toJid(d.kreditur)) }, { quoted: msg });
    }
    let m = a.match(/^lunas\s+(.+)$/i);
    if (m) {
      const idm = m[1].trim().match(/^#?(\d+)$/);
      let hit;
      if (idm && !target) hit = all.filter((d) => d.id === +idm[1] && d.kreditur === senderNum && !d.lunas);
      else if (target) hit = all.filter((d) => d.debitur === env.numOf(target) && d.kreditur === senderNum && !d.lunas);
      else return reply("Format: *.hutang lunas <ID>* atau *.hutang lunas @tag*");
      if (!hit.length) return reply("Tidak ada utang aktif yang cocok. Lihat *.hutang list*");
      hit.forEach((d) => { d.lunas = true; d.paidAt = Date.now(); }); env.saveDB();
      return reply(`✅ ${hit.length} utang ditandai *lunas* (${rp(hit.reduce((s, d) => s + d.amt, 0))}).`);
    }
    m = a.match(/^(?:hapus|del)\s+#?(\d+)$/i);
    if (m) {
      const i = all.findIndex((d) => d.id === +m[1] && d.kreditur === senderNum);
      if (i < 0) return reply(`Utang #${m[1]} tidak ditemukan.`);
      all.splice(i, 1); env.saveDB(); return reply(`🗑️ Utang #${m[1]} dihapus.`);
    }
    // tambah
    if (!target) return reply("Tag atau reply orang yang berutang.\n\n" + usage);
    const debNum = env.numOf(target);
    if (debNum === senderNum) return reply("Tidak bisa mencatat utang ke diri sendiri.");
    const words = stripMentions(a).split(/\s+/).filter(Boolean);
    const idx = words.findIndex((w) => isAmountTok(w));
    if (idx < 0) return reply("Jumlah tidak terbaca.\n\n" + usage);
    const val = parseRp(words[idx]);
    if (!val || val <= 0 || val > 1e12) return reply("Jumlah tidak valid.\n\n" + usage);
    const ket = words.filter((_, i) => i !== idx).join(" ").slice(0, 80);
    const d = { id: nextId("hutang"), kreditur: senderNum, debitur: debNum, debJid: target, amt: val, ket, d: wibDate(), ts: Date.now(), lunas: false, lastTagih: 0 };
    all.push(d); env.saveDB();
    const tot = all.filter((x) => x.kreditur === senderNum && x.debitur === debNum && !x.lunas).reduce((s, x) => s + x.amt, 0);
    return sock.sendMessage(jid, { text: `🧾 Utang dicatat (#${d.id})\n👤 @${debNum} berutang *${rp(val)}*${ket ? "\n📝 " + ket : ""}\n\nTotal utang @${debNum} padamu: *${rp(tot)}*\n_Kirim pengingat dengan *.tagih*_`, mentions: [target] }, { quoted: msg });
  }

  async function cmdTagih(ctx) {
    const { reply, senderNum, sock, jid, msg, target, isGroup } = ctx;
    const COOLDOWN = 12 * 3600 * 1000;
    let mine = debts().filter((d) => d.kreditur === senderNum && !d.lunas);
    if (target) mine = mine.filter((d) => d.debitur === env.numOf(target));
    if (!mine.length) return reply(target ? "Orang itu tidak punya utang aktif padamu." : "Tidak ada yang perlu ditagih. 🎉\nCatat dulu: *.hutang @tag 50rb*");
    const by = new Map();
    for (const d of mine) (by.get(d.debitur) || by.set(d.debitur, []).get(d.debitur)).push(d);
    let sent = 0, skipped = [];
    for (const [num, arr] of by) {
      if (Date.now() - Math.max(...arr.map((d) => d.lastTagih || 0)) < COOLDOWN) { skipped.push(num); continue; }
      const total = arr.reduce((s, d) => s + d.amt, 0);
      const jidDeb = arr[0].debJid || env.toJid(num);
      const detail = arr.map((d) => `• ${rp(d.amt)}${d.ket ? " (" + d.ket + ")" : ""} — ${d.d.slice(5)}`).join("\n");
      const text = `Halo @${num} 👋\nIni pengingat sopan dari @${senderNum}: kamu masih punya catatan utang sebesar *${rp(total)}*.\n${detail}\n\nKalau sudah ada rezekinya, mohon dibayar ya. Terima kasih banyak 🙏`;
      try {
        await sock.sendMessage(isGroup ? jid : jidDeb, { text, mentions: [jidDeb, env.toJid(senderNum)] }, isGroup ? { quoted: msg } : undefined);
        arr.forEach((d) => { d.lastTagih = Date.now(); }); sent++;
        await env.sleep(1500);
      } catch (e) { skipped.push(num); }
    }
    env.saveDB();
    let t = `📨 Pengingat terkirim ke *${sent}* orang${isGroup ? " (di grup ini)" : " (lewat chat pribadi mereka)"}.`;
    if (skipped.length) t += `\n⏳ Dilewati (sudah ditagih <12 jam / gagal): ${skipped.map((n) => "+" + n).join(", ")}`;
    return reply(t);
  }

  // ===================== Split bill =====================
  async function cmdSplitBill(ctx) {
    const { args, reply } = ctx;
    const usage = `🍽️ *Split Bill*\nFormat: *.splitbill <total> <jumlah orang> [pajak 10] [service 5] [diskon 20]*\n\nContoh:\n*.splitbill 250000 5*\n*.splitbill 400rb 4 pajak 10 service 5*\n\nPer orang:\n*.splitbill Andi=50rb, Budi=75rb, Cici=60rb, pajak 10, service 5*\n_Dengan pajak/service, total = harga sebelum pajak. Service dihitung dulu, pajak dikenakan atas (harga + service)._`;
    let a = args.trim();
    if (!a) return reply(usage);
    let tax = 0, svc = 0, disc = 0;
    a = a.replace(/\b(pajak|ppn|tax)\s*[:=]?\s*(\d+(?:[.,]\d+)?)\s*%?/gi, (_, __, n) => { tax = parseFloat(n.replace(",", ".")); return " "; })
      .replace(/\b(service|servis|sc)\s*[:=]?\s*(\d+(?:[.,]\d+)?)\s*%?/gi, (_, __, n) => { svc = parseFloat(n.replace(",", ".")); return " "; })
      .replace(/\b(diskon|disc)\s*[:=]?\s*(\d+(?:[.,]\d+)?)\s*%?/gi, (_, __, n) => { disc = parseFloat(n.replace(",", ".")); return " "; })
      .trim();
    if (tax > 100 || svc > 100 || disc > 100) return reply("Persentase tidak valid.\n\n" + usage);
    const factor = (1 - disc / 100) * (1 + svc / 100) * (1 + tax / 100);
    const round100 = (n) => Math.ceil(n / 100) * 100;
    if (a.includes("=")) {
      const people = [];
      for (const part of a.split(/[\n,;]+/)) {
        const mt = part.match(/^\s*(.+?)\s*=\s*(.+?)\s*$/);
        if (!mt) continue;
        const v = parseRp(mt[2]);
        if (v === null || v < 0) return reply(`Nominal "${mt[2]}" tidak terbaca.\n\n` + usage);
        people.push([mt[1].slice(0, 20), v]);
      }
      if (people.length < 1 || people.length > 40) return reply("Isi 1–40 orang.\n\n" + usage);
      const sub = people.reduce((s, p) => s + p[1], 0);
      let t = `🍽️ *Split Bill*\nSubtotal: ${rp(sub)}\n` + (disc ? `Diskon ${disc}%\n` : "") + (svc ? `Service ${svc}%\n` : "") + (tax ? `Pajak ${tax}%\n` : "");
      t += `\n` + people.map(([n, v]) => `• ${n}: *${rp(Math.round(v * factor))}*`).join("\n");
      t += `\n\n🧾 Total: *${rp(Math.round(sub * factor))}*`;
      return reply(t);
    }
    const words = a.split(/\s+/);
    const total = parseRp(words[0]);
    const n = parseInt(words[1], 10);
    if (!total || !n || n < 1 || n > 100 || !/^\d+$/.test(words[1] || "")) return reply(usage);
    const grand = total * factor, per = grand / n;
    let t = `🍽️ *Split Bill*\nTotal: ${rp(total)}\n` + (disc ? `Diskon ${disc}%\n` : "") + (svc ? `Service ${svc}%\n` : "") + (tax ? `Pajak ${tax}%\n` : "");
    t += `${tax || svc || disc ? `Total akhir: ${rp(grand)}\n` : ""}Jumlah orang: ${n}\n\n💸 Per orang: *${rp(Math.round(per))}*`;
    if (round100(per) !== Math.round(per)) t += `\n_(dibulatkan ke atas: ${rp(round100(per))})_`;
    return reply(t);
  }

  // ===================== Cicilan =====================
  async function cmdCicilan(ctx) {
    const { args, reply } = ctx;
    const usage = `🏦 *Kalkulator Cicilan*\nFormat: *.cicilan <pokok> <bunga %/tahun> <tenor> [flat|anuitas|efektif]*\n\nContoh:\n*.cicilan 20jt 12 24* (24 bulan)\n*.cicilan 15000000 10 2tahun anuitas*`;
    const w = args.trim().split(/\s+/).filter(Boolean);
    if (w.length < 3) return reply(usage);
    const P = parseRp(w[0]);
    const rate = pct(w[1]);
    const tm = w[2].toLowerCase().match(/^(\d+)\s*(bulan|bln|b|tahun|thn|th|t)?$/);
    if (!P || P <= 0 || rate === null || rate < 0 || rate > 200 || !tm) return reply("Input tidak terbaca.\n\n" + usage);
    let n = +tm[1]; if (/^(tahun|thn|th|t)$/.test(tm[2] || "")) n *= 12;
    if (n < 1 || n > 480) return reply("Tenor 1–480 bulan.\n\n" + usage);
    const mode = (w[3] || "").toLowerCase();
    const i = rate / 100 / 12;
    // Flat
    const flatInterest = P * (rate / 100) * (n / 12), flatMonthly = (P + flatInterest) / n;
    // Anuitas
    const pmt = i === 0 ? P / n : (P * i) / (1 - Math.pow(1 + i, -n));
    // Efektif menurun (pokok tetap)
    const pokokTetap = P / n;
    let t = `🏦 *Simulasi Cicilan*\nPokok: ${rp(P)} • Bunga: ${dec(rate)}%/thn • Tenor: ${n} bln\n`;
    if (!mode || mode === "flat") t += `\n*Bunga flat*\nCicilan/bln: *${rp(flatMonthly)}*\nTotal bunga: ${rp(flatInterest)}\nTotal bayar: ${rp(P + flatInterest)}\n`;
    if (!mode || mode === "anuitas") t += `\n*Anuitas (bunga efektif, cicilan tetap)*\nCicilan/bln: *${rp(pmt)}*\nTotal bunga: ${rp(pmt * n - P)}\nTotal bayar: ${rp(pmt * n)}\n`;
    if (mode === "efektif") {
      const first = pokokTetap + P * i, last = pokokTetap + pokokTetap * i;
      t += `\n*Efektif (pokok tetap, bunga menurun)*\nBulan 1: *${rp(first)}*\nBulan ${n}: *${rp(last)}*\nTotal bunga: ${rp((P * i * (n + 1)) / 2)}\nTotal bayar: ${rp(P + (P * i * (n + 1)) / 2)}\n`;
    }
    if (!mode || mode === "anuitas") {
      let bal = P; const rows = [];
      for (let k = 1; k <= n; k++) {
        const bung = bal * i, pok = pmt - bung; bal = Math.max(0, bal - pok);
        if (k <= 3 || k === n) rows.push(`${String(k).padStart(2)} | ${thousands(pok)} | ${thousands(bung)} | ${thousands(bal)}`);
        else if (k === 4 && n > 4) rows.push("...");
      }
      t += "\n```Bln | Pokok | Bunga | Sisa\n" + rows.join("\n") + "```\n";
    }
    t += "_Estimasi; biaya admin/provisi/asuransi belum dihitung._";
    return reply(t);
  }

  // ===================== Harga emas (dunia) =====================
  let goldCache = { at: 0, v: null };
  async function goldPerGram() {
    if (goldCache.v && Date.now() - goldCache.at < 10 * 60 * 1000) return goldCache.v;
    const OZ = 31.1034768;
    const tries = [
      async () => { // goldprice.org: xauPrice = IDR per troy oz
        const j = JSON.parse((await env.getBuf("https://data-asg.goldprice.org/dbXRates/IDR", { "User-Agent": "Mozilla/5.0" }, { timeout: 12000 })).toString());
        const p = Number(j?.items?.[0]?.xauPrice);
        if (!(p > 0)) throw new Error("kosong");
        return { perGram: p / OZ, src: "goldprice.org (XAU/IDR)" };
      },
      async () => { // gold-api.com (USD/oz) x kurs USD->IDR
        const g = JSON.parse((await env.getBuf("https://api.gold-api.com/price/XAU", {}, { timeout: 12000 })).toString());
        const k = JSON.parse((await env.getBuf("https://open.er-api.com/v6/latest/USD", {}, { timeout: 12000 })).toString());
        const usd = Number(g?.price), idr = Number(k?.rates?.IDR);
        if (!(usd > 0) || !(idr > 0)) throw new Error("kosong");
        return { perGram: (usd * idr) / OZ, src: "gold-api.com (XAU/USD) × kurs open.er-api.com", usd, idr };
      },
    ];
    for (const fn of tries) { try { const v = await fn(); goldCache = { at: Date.now(), v }; return v; } catch {} }
    return null;
  }
  async function cmdEmas(ctx) {
    const g = await goldPerGram();
    if (!g) return ctx.reply("❌ Harga emas dunia tidak bisa diambil sekarang (sumber tidak terjangkau).\nCoba lagi nanti, atau cek langsung di situs penjual emas (Antam, Pegadaian).");
    const p = g.perGram;
    return ctx.reply(`🥇 *Harga Emas Dunia (estimasi)*\n1 gram (24K): *${rp(p)}*\n5 gram: ${rp(p * 5)}\n10 gram: ${rp(p * 10)}\n100 gram: ${rp(p * 100)}\n\n_Estimasi dari harga emas dunia, bukan harga toko/Antam (harga jual-beli toko berbeda karena margin dan pajak)._\nSumber: ${g.src}\n${longDate()}`);
  }

  // ===================== Zakat =====================
  async function cmdZakat(ctx) {
    const { args, reply } = ctx;
    const usage = `🕌 *Kalkulator Zakat*\nFormat:\n*.zakat maal <total harta> [harga=<per gram>]*\n*.zakat penghasilan <gaji per bulan> [tambahan per bulan] [harga=...]*\n*.zakat emas <gram> [harga=...]*\n\nContoh:\n*.zakat maal 250jt*\n*.zakat penghasilan 8jt*\n*.zakat emas 100*\n_Nisab = 85 gram emas, zakat 2,5%. Harga emas otomatis dari harga dunia, atau isi sendiri dengan harga=1500000._`;
    let a = args.trim();
    if (!a) return reply(usage);
    let price = null;
    a = a.replace(/\bharga\s*=\s*(\S+)/i, (_, v) => { price = parseRp(v); return ""; }).trim();
    const w = a.split(/\s+/);
    const kind = (w.shift() || "").toLowerCase();
    if (!["maal", "harta", "penghasilan", "profesi", "gaji", "emas"].includes(kind)) return reply(usage);
    let srcNote = "harga emas diisi manual";
    if (!price) {
      const g = await goldPerGram();
      if (!g) return reply("❌ Harga emas tidak bisa diambil otomatis.\nIsi sendiri: contoh *.zakat " + kind + " " + (w[0] || "250jt") + " harga=1500000* (harga emas per gram).");
      price = Math.round(g.perGram); srcNote = "harga emas dunia (estimasi), bukan harga toko";
    }
    const nisab = 85 * price;
    if (kind === "emas") {
      const gram = parseFloat((w[0] || "").replace(",", "."));
      if (!(gram > 0)) return reply("Isi jumlah gram.\nContoh: *.zakat emas 100*");
      const wajib = gram >= 85;
      return reply(`🕌 *Zakat Emas*\nEmas: ${dec(gram)} g • Nisab: 85 g (${rp(nisab)})\n${wajib ? `✅ Mencapai nisab (jika sudah dimiliki 1 tahun/haul)\nZakat: *${dec(gram * 0.025, 3)} g* ≈ *${rp(gram * 0.025 * price)}*` : "Belum mencapai nisab, belum wajib zakat."}\n\n_Harga ${rp(price)}/g — ${srcNote}._`);
    }
    const val = parseRp(w[0]);
    if (!val || val <= 0) return reply("Jumlah tidak terbaca.\n\n" + usage);
    if (kind === "maal" || kind === "harta") {
      const wajib = val >= nisab;
      return reply(`🕌 *Zakat Maal*\nHarta (setelah utang jangka pendek): ${rp(val)}\nNisab 85 g emas: ${rp(nisab)}\n${wajib ? `✅ Mencapai nisab (jika sudah 1 tahun/haul)\nZakat 2,5%: *${rp(val * 0.025)}*` : "Belum mencapai nisab, belum wajib zakat."}\n\n_Harga emas ${rp(price)}/g — ${srcNote}. Hitungan ini estimasi; konsultasikan ke lembaga zakat (BAZNAS/LAZ)._`);
    }
    const extra = w[1] ? parseRp(w[1]) || 0 : 0;
    const monthly = val + extra, yearly = monthly * 12;
    const wajib = yearly >= nisab;
    return reply(`🕌 *Zakat Penghasilan*\nPenghasilan/bln: ${rp(monthly)} (setahun ${rp(yearly)})\nNisab setahun (85 g emas): ${rp(nisab)} (≈ ${rp(nisab / 12)}/bln)\n${wajib ? `✅ Mencapai nisab\nZakat 2,5%: *${rp(monthly * 0.025)} / bulan* (≈ ${rp(yearly * 0.025)}/tahun)` : "Belum mencapai nisab, belum wajib zakat."}\n\n_Harga emas ${rp(price)}/g — ${srcNote}. Estimasi; kebutuhan pokok/utang boleh dikurangkan menurut pendapat sebagian ulama._`);
  }

  // ===================== Pajak PPh 21 =====================
  function pph21(pkp) {
    const L = [[60e6, 0.05], [250e6, 0.15], [500e6, 0.25], [5e9, 0.30], [Infinity, 0.35]];
    let rest = pkp, prev = 0, tax = 0; const parts = [];
    for (const [lim, r] of L) {
      if (rest <= 0) break;
      const slab = Math.min(rest, lim - prev); tax += slab * r; parts.push([slab, r]); rest -= slab; prev = lim;
    }
    return { tax, parts };
  }
  function ptkpOf(status) {
    const m = String(status).toLowerCase().match(/^(tk|k)\/?(\d)$/);
    if (!m) return null;
    const t = Math.min(3, +m[2]);
    return { v: (m[1] === "k" ? 58.5e6 : 54e6) + t * 4.5e6, label: `${m[1].toUpperCase()}/${t}` };
  }
  async function cmdPajak(ctx) {
    const { args, reply } = ctx;
    const usage = `🧮 *Kalkulator PPh 21 (estimasi)*\nFormat: *.pajak <gaji per bulan> [status] [bonus=<setahun>]*\nStatus: tk0–tk3 (lajang), k0–k3 (menikah), default tk0.\n\nContoh:\n*.pajak 10jt*\n*.pajak 15jt k1 bonus=30jt*`;
    const w = args.trim().split(/\s+/).filter(Boolean);
    if (!w.length) return reply(usage);
    const gaji = parseRp(w[0]);
    if (!gaji || gaji <= 0) return reply("Gaji tidak terbaca.\n\n" + usage);
    let status = "tk0", bonus = 0;
    for (const x of w.slice(1)) {
      const bm = x.match(/^(?:bonus|thr)=(.+)$/i);
      if (bm) bonus = parseRp(bm[1]) || 0; else if (ptkpOf(x)) status = x; else return reply(`Opsi "${x}" tidak dikenali.\n\n` + usage);
    }
    const pt = ptkpOf(status);
    const bruto = gaji * 12 + bonus;
    const bj = Math.min(bruto * 0.05, 6e6);
    const neto = bruto - bj;
    const pkp = Math.max(0, Math.floor((neto - pt.v) / 1000) * 1000);
    const { tax, parts } = pph21(pkp);
    return reply(`🧮 *Estimasi PPh 21 Tahunan*\nGaji bruto setahun: ${rp(bruto)}${bonus ? ` (termasuk bonus ${rp(bonus)})` : ""}\nBiaya jabatan (5%, maks 6 jt): -${rp(bj)}\nPTKP ${pt.label}: -${rp(pt.v)}\nPKP: *${rp(pkp)}*\n\n` +
      (parts.length ? parts.map(([s, r]) => `• ${rp(s)} × ${Math.round(r * 100)}%`).join("\n") + "\n\n" : "") +
      `💸 Pajak setahun: *${rp(tax)}*\n📆 Rata-rata/bln: *${rp(tax / 12)}*\n\n_Estimasi sederhana tarif progresif UU HPP (tanpa iuran pensiun/JHT dan tanpa tarif efektif bulanan TER). Hitungan resmi mengikuti slip/pemotong pajak._`);
  }

  // ===================== BBM (tabel dikelola owner) =====================
  async function cmdBbm(ctx) {
    const { args, reply, isOwner } = ctx;
    const s = env.settings;
    const a = args.trim();
    const mt = a.match(/^(set|ubah)\s+([\s\S]+)$/i);
    if (mt) {
      if (!isOwner) return reply("👑 Hanya owner yang bisa mengubah tabel harga BBM.");
      const tb = (s.zfBbm = s.zfBbm || { items: {}, updated: 0 });
      let n = 0;
      for (const part of mt[2].split(/[\n;,]+/)) {
        const m = part.match(/^\s*(.+?)\s*=\s*(.+?)\s*$/);
        if (!m) continue;
        const v = parseRp(m[2]);
        if (!v || v < 1000 || v > 1e6) return reply(`Harga "${m[2]}" tidak valid.\nContoh: *.bbm set pertalite=10000; pertamax=12200*`);
        tb.items[m[1].toLowerCase().slice(0, 24)] = v; n++;
      }
      if (!n) return reply("Format: *.bbm set <nama>=<harga per liter>*\nContoh: *.bbm set pertalite=10000; pertamax=12200*");
      tb.updated = Date.now(); env.saveSettings();
      return reply(`✅ ${n} harga BBM disimpan.`);
    }
    const del = a.match(/^hapus\s+(.+)$/i);
    if (del) {
      if (!isOwner) return reply("👑 Hanya owner.");
      const tb = s.zfBbm; const k = del[1].toLowerCase().trim();
      if (!tb || !(k in tb.items)) return reply("Nama BBM tidak ada di tabel.");
      delete tb.items[k]; tb.updated = Date.now(); env.saveSettings(); return reply(`🗑️ ${k} dihapus dari tabel.`);
    }
    const tb = s.zfBbm;
    if (!tb || !Object.keys(tb.items).length) {
      return reply(`⛽ *Harga BBM*\nTabel harga belum diisi. Harga BBM berubah berkala dan tidak ada sumber otomatis yang stabil, jadi bot tidak menebak angka.\n\n${isOwner ? "Isi sendiri (cek harga resmi Pertamina):\n*.bbm set pertalite=<harga>; pertamax=<harga>; dexlite=<harga>*" : "Minta owner mengisinya dengan *.bbm set <nama>=<harga>*, atau cek langsung di situs/aplikasi MyPertamina."}`);
    }
    const lines = Object.entries(tb.items).map(([k, v]) => `• ${k[0].toUpperCase() + k.slice(1)}: *${rp(v)}*/liter`);
    return reply(`⛽ *Harga BBM*\n${lines.join("\n")}\n\n🕒 Diperbarui owner: ${longDate(tb.updated)}\n_Harga dicatat manual oleh owner dan bisa berbeda antar wilayah/waktu. Cek MyPertamina untuk harga terbaru._`);
  }

  // ===================== Dokumen: util =====================
  const MAX_FILE = 40 * 1024 * 1024;
  const PDF_MIME = "application/pdf";
  const DOCX_MIME = "application/vnd.openxmlformats-officedocument.wordprocessingml.document";
  const docOf = (m) => {
    if (!m) return null;
    m = env.unwrap(m) || m;
    return m.documentMessage || m.documentWithCaptionMessage?.message?.documentMessage || null;
  };
  const findDoc = (msg, ctxInfo) => docOf(msg?.message) || docOf(ctxInfo?.quotedMessage) || docOf((env.unwrap(msg?.message) || {}).extendedTextMessage?.contextInfo?.quotedMessage);
  const isPdf = (d) => /pdf/i.test(d?.mimetype || "") || /\.pdf$/i.test(d?.fileName || "");
  const isWord = (d) => /\.(docx?|dotx?|rtf|odt)$/i.test(d?.fileName || "") || /(msword|wordprocessingml|opendocument\.text)/i.test(d?.mimetype || "");
  const baseName = (n, fb) => String(n || fb).replace(/\.[^.]+$/, "").replace(/[^\w\-. ()À-ɏ]+/g, "_").slice(0, 60) || fb;

  const PATHS = (process.env.PATH || "").split(path.delimiter).concat(["/data/data/com.termux/files/usr/bin", "/usr/bin", "/usr/local/bin", "/opt/libreoffice/program"]);
  const haveCache = new Map();
  function have(bin) {
    if (haveCache.has(bin)) return haveCache.get(bin);
    let ok = false;
    for (const p of PATHS) { try { if (p && fs.existsSync(path.join(p, bin))) { ok = true; break; } } catch {} }
    haveCache.set(bin, ok); return ok;
  }
  async function getDocBuf(d) {
    if (Number(d.fileLength || 0) > MAX_FILE) throw new Error(`File terlalu besar (maks ${env.fmtSize(MAX_FILE)}).`);
    const b = await env.download({ type: "document", content: d });
    if (b.length > MAX_FILE) throw new Error(`File terlalu besar (maks ${env.fmtSize(MAX_FILE)}).`);
    return b;
  }
  const needDocReply = (ctx, what, cmd) => ctx.reply(`Reply (atau kirim) file *${what}* dengan *.${cmd}*`);
  const sendDoc = (ctx, buf, mimetype, fileName, caption) => ctx.sock.sendMessage(ctx.jid, { document: buf, mimetype, fileName, caption }, { quoted: ctx.msg });
  const mkTmpDir = (pfx) => { const d = path.join(env.TMP, pfx + Date.now() + "_" + Math.random().toString(36).slice(2, 7)); fs.mkdirSync(d, { recursive: true }); return d; };
  const rmDir = (d) => { try { fs.rmSync(d, { recursive: true, force: true }); } catch {} };

  async function pageCount(file) {
    if (have("qpdf")) { try { const n = parseInt(String(await env.run("qpdf", ["--show-npages", file])).trim(), 10); if (n > 0) return n; } catch {} }
    if (have("pdfinfo")) { try { const m = String(await env.run("pdfinfo", [file])).match(/Pages:\s+(\d+)/); if (m) return +m[1]; } catch {} }
    throw new Error("NOTOOL");
  }
  const NOTOOL_MSG = "Alat PDF belum terpasang. Jalankan di Termux:\n*pkg install poppler qpdf*\nlalu coba lagi.";

  async function extractPages(inp, pages, out) {
    if (have("qpdf")) { await env.run("qpdf", ["--empty", "--pages", inp, pages.join(","), "--", out], { timeout: 120000 }); return; }
    if (have("pdfseparate") && have("pdfunite")) {
      const dir = mkTmpDir("sp_");
      try {
        const parts = [];
        for (const p of pages) { const f = path.join(dir, `p${p}.pdf`); await env.run("pdfseparate", ["-f", String(p), "-l", String(p), inp, f], { timeout: 60000 }); parts.push(f); }
        if (parts.length === 1) fs.copyFileSync(parts[0], out); else await env.run("pdfunite", [...parts, out], { timeout: 120000 });
      } finally { rmDir(dir); }
      return;
    }
    throw new Error("NOTOOL");
  }
  function parsePages(spec, n) {
    const set = [];
    for (const part of spec.split(/[,\s]+/).filter(Boolean)) {
      const m = part.match(/^(\d+)(?:-(\d+))?$/);
      if (!m) return { error: `Bagian "${part}" tidak valid.` };
      let a = +m[1], b = m[2] ? +m[2] : a;
      if (a > b) [a, b] = [b, a];
      if (a < 1 || b > n) return { error: `Halaman di luar rentang (PDF ini ${n} halaman).` };
      for (let i = a; i <= b; i++) if (!set.includes(i)) set.push(i);
    }
    return { pages: set };
  }

  // ---- pdf2word / word2pdf ----
  const sofficeBin = () => (have("soffice") ? "soffice" : have("libreoffice") ? "libreoffice" : null);
  async function sofficeConvert(inFile, outDir, target, extraArgs = []) {
    const bin = sofficeBin();
    const prof = mkTmpDir("lo_");
    try {
      await env.run(bin, [`-env:UserInstallation=file://${prof}`, "--headless", "--norestore", ...extraArgs, "--convert-to", target, "--outdir", outDir, inFile], { timeout: 180000 });
    } finally { rmDir(prof); }
  }
  async function cmdPdf2Word(ctx) {
    const d = findDoc(ctx.msg, ctx.ctxInfo);
    if (!d || !isPdf(d)) return needDocReply(ctx, "PDF", "pdf2word");
    const pyOk = have("python3") && (await env.run("python3", ["-c", "import pdf2docx"]).then(() => true, () => false));
    const lo = sofficeBin();
    if (!pyOk && !lo) {
      return ctx.reply("❌ Belum ada alat konversi PDF→Word.\nPasang salah satu di Termux:\n• *pkg install python* lalu *pip install pdf2docx --break-system-packages* (hasil terbaik)\n• atau LibreOffice jika tersedia untuk perangkatmu (*pkg install x11-repo && pkg install libreoffice*)\nSetelah terpasang, ulangi perintah ini.");
    }
    ctx.react("⏳");
    const dir = mkTmpDir("p2w_");
    try {
      const buf = await getDocBuf(d);
      const inp = path.join(dir, "in.pdf"), out = path.join(dir, "out.docx");
      fs.writeFileSync(inp, buf);
      let how = "";
      if (pyOk) {
        try {
          await env.run("python3", ["-c", "import sys\nfrom pdf2docx import Converter\nc=Converter(sys.argv[1])\nc.convert(sys.argv[2])\nc.close()", inp, out], { timeout: 240000 });
          how = "pdf2docx";
        } catch (e) { if (!lo) throw e; }
      }
      if (!fs.existsSync(out) && lo) {
        await sofficeConvert(inp, dir, "docx:MS Word 2007 XML", ["--infilter=writer_pdf_import"]);
        const gen = path.join(dir, "in.docx");
        if (fs.existsSync(gen)) { fs.renameSync(gen, out); how = "LibreOffice"; }
      }
      if (!fs.existsSync(out)) throw new Error("hasil konversi tidak terbentuk (PDF hasil scan/gambar biasanya tidak bisa)");
      const res = fs.readFileSync(out);
      await sendDoc(ctx, res, DOCX_MIME, baseName(d.fileName, "dokumen") + ".docx", `📝 PDF → Word (${how}) • ${env.fmtSize(res.length)}\n_Tata letak kompleks/PDF hasil scan bisa berubah._`);
      return ctx.react("✅");
    } catch (e) { return ctx.reply("❌ Gagal mengubah PDF: " + String(e.message).slice(0, 160)); }
    finally { rmDir(dir); }
  }
  async function cmdWord2Pdf(ctx) {
    const d = findDoc(ctx.msg, ctx.ctxInfo);
    if (!d || !isWord(d)) return needDocReply(ctx, "Word (.docx/.doc)", "word2pdf");
    if (!sofficeBin()) return ctx.reply("❌ LibreOffice belum terpasang, jadi Word→PDF belum bisa.\nDi Termux: *pkg install x11-repo && pkg install libreoffice* (jika tersedia untuk perangkatmu).\nAlternatif: buka file di aplikasi Word/WPS lalu *Simpan sebagai PDF*.");
    ctx.react("⏳");
    const dir = mkTmpDir("w2p_");
    try {
      const buf = await getDocBuf(d);
      const ext = (String(d.fileName || "").match(/\.[a-z0-9]+$/i) || [".docx"])[0].toLowerCase();
      const inp = path.join(dir, "in" + ext);
      fs.writeFileSync(inp, buf);
      await sofficeConvert(inp, dir, "pdf");
      const out = path.join(dir, "in.pdf");
      if (!fs.existsSync(out)) throw new Error("hasil konversi tidak terbentuk");
      const res = fs.readFileSync(out);
      await sendDoc(ctx, res, PDF_MIME, baseName(d.fileName, "dokumen") + ".pdf", `📄 Word → PDF • ${env.fmtSize(res.length)}`);
      return ctx.react("✅");
    } catch (e) { return ctx.reply("❌ Gagal mengubah ke PDF: " + String(e.message).slice(0, 160)); }
    finally { rmDir(dir); }
  }

  // ---- merge PDF (sesi) ----
  const mergeSessions = new Map(); // "chat|nomor" -> {files:[{path,name,size}], dir, t}
  const MERGE_TTL = 10 * 60 * 1000, MERGE_MAX = 20;
  const dropMerge = (key) => { const s = mergeSessions.get(key); if (s) { rmDir(s.dir); mergeSessions.delete(key); } };
  async function addMergeFile(key, d, msg, sock, jid) {
    const s = mergeSessions.get(key);
    if (!s) return false;
    if (s.files.length >= MERGE_MAX) { await sock.sendMessage(jid, { text: `Maksimal ${MERGE_MAX} file per sesi. Ketik *.mergepdf selesai*.` }, { quoted: msg }); return true; }
    const total = s.files.reduce((x, f) => x + f.size, 0);
    if (total + Number(d.fileLength || 0) > MAX_FILE) { await sock.sendMessage(jid, { text: `Total ukuran melebihi ${env.fmtSize(MAX_FILE)}. Ketik *.mergepdf selesai* untuk menggabungkan yang sudah masuk.` }, { quoted: msg }); return true; }
    const buf = await getDocBuf(d);
    const p = path.join(s.dir, `f${s.files.length + 1}.pdf`);
    fs.writeFileSync(p, buf);
    s.files.push({ path: p, name: d.fileName || p, size: buf.length });
    s.t = Date.now();
    await sock.sendMessage(jid, { text: `📎 PDF ke-${s.files.length} diterima: ${String(d.fileName || "").slice(0, 40)} (${env.fmtSize(buf.length)})\nKirim lagi, atau ketik *.mergepdf selesai*.` }, { quoted: msg });
    return true;
  }
  async function cmdMergePdf(ctx) {
    const key = `${ctx.jid}|${ctx.senderNum}`;
    const a = ctx.args.trim().toLowerCase();
    const sess = mergeSessions.get(key);
    const usage = "🧷 *Gabung PDF*\nFormat:\n1) *.mergepdf* → mulai sesi\n2) kirim 2+ file PDF (sesuai urutan kirim)\n3) *.mergepdf selesai* → hasil digabung\n*.mergepdf batal* → batalkan\n_Sesi otomatis berakhir setelah 10 menit tanpa aktivitas._";
    if (a === "batal") { if (!sess) return ctx.reply("Tidak ada sesi gabung PDF."); dropMerge(key); return ctx.reply("❎ Sesi gabung PDF dibatalkan."); }
    if (a === "selesai" || a === "done" || a === "gabung") {
      if (!sess) return ctx.reply("Belum ada sesi. Mulai dengan *.mergepdf* lalu kirim file PDF.");
      if (sess.files.length < 2) return ctx.reply(`Baru ${sess.files.length} file. Kirim minimal 2 PDF dulu.`);
      if (!have("pdfunite") && !have("qpdf")) return ctx.reply(NOTOOL_MSG);
      ctx.react("⏳");
      const out = path.join(sess.dir, "merged.pdf");
      try {
        const files = sess.files.map((f) => f.path);
        if (have("pdfunite")) await env.run("pdfunite", [...files, out], { timeout: 180000 });
        else await env.run("qpdf", ["--empty", "--pages", ...files, "--", out], { timeout: 180000 });
        const res = fs.readFileSync(out);
        const n = sess.files.length;
        dropMerge(key);
        await sendDoc(ctx, res, PDF_MIME, "gabungan-" + Date.now().toString(36) + ".pdf", `🧷 ${n} PDF digabung • ${env.fmtSize(res.length)}`);
        return ctx.react("✅");
      } catch (e) { return ctx.reply("❌ Gagal menggabung (ada PDF yang rusak/terkunci sandi?): " + String(e.message).slice(0, 140)); }
    }
    if (a && a !== "mulai") return ctx.reply(usage);
    const d = findDoc(ctx.msg, ctx.ctxInfo);
    if (sess) {
      if (d && isPdf(d)) { try { await addMergeFile(key, d, ctx.msg, ctx.sock, ctx.jid); } catch (e) { await ctx.reply("❌ " + e.message); } return; }
      return ctx.reply(`Sesi aktif: ${sess.files.length} file masuk. Kirim PDF lagi, atau *.mergepdf selesai* / *.mergepdf batal*.`);
    }
    if (!have("pdfunite") && !have("qpdf")) return ctx.reply(NOTOOL_MSG);
    mergeSessions.set(key, { files: [], dir: mkTmpDir("mg_"), t: Date.now() });
    if (d && isPdf(d)) { try { await addMergeFile(key, d, ctx.msg, ctx.sock, ctx.jid); } catch (e) { await ctx.reply("❌ " + e.message); } return; }
    return ctx.reply("🧷 Sesi gabung PDF dimulai.\nKirim file PDF (minimal 2) sesuai urutan yang diinginkan, lalu ketik *.mergepdf selesai*.");
  }

  // ---- split PDF ----
  async function cmdSplitPdf(ctx) {
    const d = findDoc(ctx.msg, ctx.ctxInfo);
    const spec = ctx.args.trim().toLowerCase();
    const usage = "✂️ *Pisah PDF*\nFormat: reply PDF dengan *.splitpdf <halaman>*\n\nContoh:\n*.splitpdf 1-3* → halaman 1 sampai 3 jadi satu PDF\n*.splitpdf 2,5* → halaman 2 dan 5\n*.splitpdf semua* → tiap halaman jadi file sendiri (maks 15 halaman)";
    if (!d || !isPdf(d)) return ctx.reply(usage);
    if (!spec) return ctx.reply(usage);
    if (!have("qpdf") && !(have("pdfseparate") && have("pdfunite"))) return ctx.reply(NOTOOL_MSG);
    const dir = mkTmpDir("spl_");
    try {
      const buf = await getDocBuf(d);
      const inp = path.join(dir, "in.pdf"); fs.writeFileSync(inp, buf);
      let n;
      try { n = await pageCount(inp); } catch (e) { return ctx.reply(e.message === "NOTOOL" ? NOTOOL_MSG : "❌ PDF tidak terbaca (rusak/terkunci sandi?)."); }
      const nm = baseName(d.fileName, "dokumen");
      ctx.react("⏳");
      if (/^(semua|all)$/.test(spec)) {
        if (n > 15) return ctx.reply(`PDF ini ${n} halaman — terlalu banyak untuk dipisah semua. Pakai rentang, contoh: *.splitpdf 1-10*`);
        for (let p = 1; p <= n; p++) {
          const out = path.join(dir, `o${p}.pdf`);
          await extractPages(inp, [p], out);
          await sendDoc(ctx, fs.readFileSync(out), PDF_MIME, `${nm}-hal${p}.pdf`, `Halaman ${p}/${n}`);
          if (p < n) await env.sleep(700);
        }
        return ctx.react("✅");
      }
      const pr = parsePages(spec, n);
      if (pr.error) return ctx.reply("❌ " + pr.error + "\n\n" + usage);
      const out = path.join(dir, "out.pdf");
      await extractPages(inp, pr.pages, out);
      const res = fs.readFileSync(out);
      await sendDoc(ctx, res, PDF_MIME, `${nm}-hal${spec.replace(/[^\d,-]/g, "")}.pdf`, `✂️ ${pr.pages.length} halaman dari ${n} • ${env.fmtSize(res.length)}`);
      return ctx.react("✅");
    } catch (e) { return ctx.reply(e.message === "NOTOOL" ? NOTOOL_MSG : "❌ Gagal memisah PDF: " + String(e.message).slice(0, 140)); }
    finally { rmDir(dir); }
  }

