      if (!fs.existsSync(out)) throw new Error("hasil tidak terbentuk");
      const res = fs.readFileSync(out);
      if (res.length >= buf.length) return ctx.reply(`ℹ️ PDF ini sudah cukup optimal (${env.fmtSize(buf.length)} → ${env.fmtSize(res.length)}), tidak bisa diperkecil lagi dengan level ini.${lvl === "kuat" ? "" : "\nCoba *.compresspdf kuat*."}`);
      const saved = Math.round((1 - res.length / buf.length) * 100);
      await sendDoc(ctx, res, PDF_MIME, baseName(d.fileName, "dokumen") + "-kecil.pdf", `🗜️ ${env.fmtSize(buf.length)} → *${env.fmtSize(res.length)}* (hemat ${saved}%)\n_${how}_`);
