    pdf2word: cmdPdf2Word, word2pdf: cmdWord2Pdf, mergepdf: cmdMergePdf, splitpdf: cmdSplitPdf, compresspdf: cmdCompressPdf, scanqr: cmdScanQr,
    surat: cmdSurat, cv: cmdCv,
