    limited: ["pdf2word", "word2pdf", "splitpdf", "compresspdf", "pdf2docx", "docx2pdf", "pisahpdf", "kompresspdf"],
    menu: [
      "┃  \".catatuang <+/-jumlah> <ket>\" → Catat uang masuk/keluar",
      "┃  \".laporanuang\" → Rekap keuangan bulanan",
      "┃  \".hutang @tag <jumlah>\" → Catat utang",
      "┃  \".tagih\" → Pengingat ke yang berutang",
      "┃  \".splitbill <total> <orang>\" → Patungan",
      "┃  \".cicilan <pokok> <bunga> <tenor>\" → Hitung cicilan",
      "┃  \".zakat maal|penghasilan|emas\" → Kalkulator zakat",
      "┃  \".pajak <gaji>\" → Estimasi PPh 21",
      "┃  \".emas\" → Harga emas dunia",
      "┃  \".bbm\" → Harga BBM",
      "┃  \".pdf2word\" / \".word2pdf\" → Konversi dokumen",
      "┃  \".mergepdf\" → Gabung PDF",
      "┃  \".splitpdf <halaman>\" → Pisah PDF",
      "┃  \".compresspdf\" → Perkecil PDF",
      "┃  \".scanqr\" → Baca QR dari foto",
      "┃  \".surat <jenis>\" → Template surat",
      "┃  \".cv\" → Buat CV lewat tanya-jawab",
    ].join("\n"),
    async handle(cmd, ctx) {
      const name = ALIAS[cmd] || cmd;
      const fn = HANDLERS[name];
      if (!fn) return false;
      try { return await fn(ctx); }
      catch (e) { console.log(`[uang_dok] .${cmd} gagal:`, e.message); return ctx.reply("❌ Terjadi kesalahan: " + String(e.message).slice(0, 140)); }
    },
