  const wibDate = (ms) => new Date(ms + 7 * 3600e3).toISOString().slice(0, 10);
  const fmtRp = (n) => (n < 0 ? "-" : "") + "Rp" + Math.round(Math.abs(n)).toLocaleString("id-ID");
  const DAYS = ["Minggu", "Senin", "Selasa", "Rabu", "Kamis", "Jumat", "Sabtu"];
  const DAY_ALIAS = { minggu: 0, ahad: 0, senin: 1, selasa: 2, rabu: 3, kamis: 4, jumat: 5, "jum'at": 5, sabtu: 6 };
  const dayOf = (w) => DAY_ALIAS[String(w || "").toLowerCase()];
