    getSock, numOf, toJid: (n) => `${n}@s.whatsapp.net`, getBuf, download, pickMedia, unwrap, tmpFile, cleanup, run,
    get canvasLib() { return canvasLib; }, canvasSem, aiOnce, geminiGenerate, toWhatsApp, imageMime, buildTextPdf, pdfName, fmtSize,
    groupMetaCached, wibParts, parseNum, todayStr, sleep,
