const grayBlock = (t) => "```\n" + String(t).replace(/\*/g, "").replace(/```/g, "'''").trim() + "\n```";

function menuSections(pushName) {
  const secs = [];
  menuText(pushName).replace(/╭━━━「 (.+?) 」━━━╮[\s\S]*?╰━+╯/g, (all, title) => { secs.push({ title: title.trim(), box: all }); return all; });
  return secs.filter((s) => !/^⚡ /.test(s.title));
}
function menuBoxCompact(box) { // kotak menu -> baris pendek (muat di layar HP, tidak terpotong)
  const out = [];
  for (let l of box.split("\n")) {
    let m = l.match(/^╭━━━「 (.+?) 」━━━╮$/); if (m) { out.push(`╭─ ${m[1]}`); continue; }
    if (/^╰━+╯$/.test(l)) { out.push("╰──────────────"); continue; }
    l = l.replace(/^┃/, "│");
    m = l.match(/^│\s+"(\.[^"]*)"\s*→\s*(.+)$/);
    if (m) { out.push(`│ ${m[1]}`, `│   ↳ ${m[2]}`); continue; }
    out.push(l);
  }
  return out.join("\n");
}
function menuCatBody(key, pushName) {
  if (key === "fakelobby") return FAKELOBBY_BOX;
  const idx = MENU_CATS.findIndex((c) => c.key === key);
  const parts = [];
  for (const s of menuSections(pushName)) {
    let ci = MENU_CATS.findIndex((c) => c.re && c.re.test(s.title));
    if (ci < 0) ci = MENU_CATS.findIndex((c) => c.key === "sistem");
    if (ci !== idx) continue;
    parts.push(menuBoxCompact(key === "sticker" ? s.box.split("\n").filter((l) => !/\.fake(ff|ml)/.test(l)).join("\n") : s.box));
  }
  return parts.join("\n\n");
}
