async function sendInteractiveMenu(sock, jid, msg, text, isOwner, variant = "b") {
  if (typeof generateWAMessageFromContent !== "function" || !proto?.Message?.InteractiveMessage) throw new Error("versi Baileys ini tidak mendukung pesan interaktif");
  const v = MENU_VARIANTS[variant] || MENU_VARIANTS.b;
  const IM = proto.Message.InteractiveMessage;
  const buttons = [{ name: "single_select", buttonParamsJson: JSON.stringify({ title: "✦ BUKA MENU", sections: menuListSections(isOwner) }) }];
  let header = IM.Header.create({ title: "", subtitle: "", hasMediaAttachment: false });
  if (v.image) {
    const media = await prepareWAMessageMedia({ image: menuImage() }, { upload: sock.waUploadToServer });
    header = IM.Header.create({ ...media, title: "", subtitle: "", hasMediaAttachment: true });
  }
  const inner = {
    messageContextInfo: { deviceListMetadata: {}, deviceListMetadataVersion: 2 },
    interactiveMessage: IM.create({
      header,
      body: IM.Body.create({ text }),
      footer: IM.Footer.create({ text: `${BOT_NAME} • Dev Alvarenza` }),
      nativeFlowMessage: IM.NativeFlowMessage.create({ buttons, messageParamsJson: "" }),
    }),
  };
  const wm = generateWAMessageFromContent(jid, { [v.wrap]: { message: inner } }, { userJid: sock.user.id, quoted: msg });
  const opts = { messageId: wm.key.id };
  if (v.biz) {
    const nodes = [{ tag: "biz", attrs: {}, content: [{ tag: "interactive", attrs: { type: "native_flow", v: "1" }, content: [{ tag: "native_flow", attrs: { v: "9", name: "mixed" } }] }] }];
    if (v.bot && !jid.endsWith("@g.us")) nodes.push({ tag: "bot", attrs: { biz_bot: "1" } });
    opts.additionalNodes = nodes;
  }
  await sock.relayMessage(jid, wm.message, opts);
}

// ---------- kartu info animasi (video berulang): foto ZYNORA, kotak info, cuaca, jam berjalan, tips berganti ----------
const MENU_TIPS = ["Bikin stiker teks: .brat <teks>", "Fake lobby: .fakeff / .fakeml", "Catat uang: .catatuang +50rb gaji", "Todo & deadline: .todo tambah <tugas>", "Unduh video: .tiktok / .ytmp4 <link>", "Tanya AI: .ai <pertanyaan>", "Semua perintah: .allmenu"];
