let menuWx = { at: 0, city: "", v: "" };
let menuLoc = { at: 0, v: null };
/** Lokasi perangkat: 1) GPS/jaringan lewat Termux:API (akurat), 2) tebakan dari IP (kasar). */
async function menuLocate() {
  if (menuLoc.v && Date.now() - menuLoc.at < 30 * 60 * 1000) return menuLoc.v;
  let v = null;
  try { // butuh: pkg install termux-api  + aplikasi Termux:API + izin lokasi
    const j = JSON.parse(await run("termux-location", ["-p", "network", "-r", "once"], { timeout: 15000 }));
    if (j && j.latitude != null) {
      let name = ""; try { const r = JSON.parse((await getBuf(`https://nominatim.openstreetmap.org/reverse?format=json&zoom=10&accept-language=id&lat=${j.latitude}&lon=${j.longitude}`, { "User-Agent": "ZynoraBot/1.0" }, { timeout: 6000 })).toString()).address || {}; name = r.city || r.town || r.county || r.city_district || r.village || r.state || ""; } catch {}
      v = { lat: j.latitude, lon: j.longitude, name, src: "gps" };
    }
  } catch {}
  if (!v) { try { const j = JSON.parse((await getBuf("https://ipwho.is/", {}, { timeout: 6000 })).toString()); if (j.success !== false && j.latitude != null) v = { lat: j.latitude, lon: j.longitude, name: j.city || j.region || "", src: "ip" }; } catch {} }
  if (v) menuLoc = { at: Date.now(), v };
  return v;
}
// Cuaca: kalau sudah ada data (walau agak lama), langsung dipakai supaya .menu tidak menunggu internet/GPS;
