  let g = f.createLinearGradient(0, Y, 0, Y + H); g.addColorStop(0, "#06030a"); g.addColorStop(1, "#12050f"); f.fillStyle = g; f.fillRect(X, Y, W, H);
  g = f.createRadialGradient(X + W / 2, Y + H / 2, 10, X + W / 2, Y + H / 2, 360); g.addColorStop(0, `rgba(255,30,60,${(0.18 + 0.12 * pulse).toFixed(2)})`); g.addColorStop(1, "rgba(255,30,60,0)"); f.fillStyle = g; f.fillRect(X, Y, W, H);
  f.save(); f.beginPath(); f.rect(X, Y, W, H); f.clip();
