    f.fillStyle = g; f.beginPath(); f.arc(ix, iy, R, 0, Math.PI * 2); f.fill();
    for (let k = 0; k < 90; k++) { const a = (k / 90) * Math.PI * 2, r0 = 26 + (k % 4) * 5, r1 = R - 6 - (k % 6) * 6; f.lineWidth = 1.2 + (k % 3) * 0.5; f.strokeStyle = `rgba(${k % 2 ? "255,170,170" : "90,0,15"},${(0.12 + 0.12 * (k % 3)).toFixed(2)})`; f.beginPath(); f.moveTo(ix + Math.cos(a) * r0, iy + Math.sin(a) * r0); f.lineTo(ix + Math.cos(a) * r1, iy + Math.sin(a) * r1); f.stroke(); }
