    f.fillStyle = `rgba(255,255,255,${(0.75 + 0.25 * Math.sin(ang * 2 + 1)).toFixed(2)})`; f.beginPath(); f.ellipse(ix - 36, iy - 30, 20, 13, -0.55, 0, Math.PI * 2); f.fill();
    f.fillStyle = "rgba(255,255,255,0.5)"; f.beginPath(); f.arc(ix + 34, iy + 36, 7, 0, Math.PI * 2); f.fill();
    g = f.createLinearGradient(0, cy - hu, 0, cy - hu + 80); g.addColorStop(0, "rgba(0,0,0,0.9)"); g.addColorStop(1, "rgba(0,0,0,0)"); f.fillStyle = g; f.fillRect(-300, cy - hu - 6, 600, 100);
