/** Peran pengirim: Owner > Admin (admin bot, atau admin grup bila di grup) > User */
async function menuRole(sock, jid, msg, isOwner) {
  if (isOwner) return "Owner";
  const num = numOf(msg.key.participant || msg.key.remoteJid || "");
  if ((settings.admins || []).includes(num)) return "Admin";
  if (jid.endsWith("@g.us")) { try { if (await isGroupAdmin(sock, jid, num)) return "Admin"; } catch {} }
  return "User";
}
const menuRoleCount = () => { // owner & admin tidak ikut dihitung sebagai user; nomor contoh (628xxx) diabaikan
  const owners = new Set([OWNER, ...(settings.owners || [])].map(String).filter((x) => /^\d{8,15}$/.test(x)));
  const admins = new Set((settings.admins || []).map(String).filter((x) => !owners.has(x)));
  const users = Object.keys(db.users || {}).filter((x) => !owners.has(x) && !admins.has(x)).length;
  return { owner: owners.size, admin: admins.size, user: users };
};
