/** ffmpeg yang menerima frame JPEG lewat pipa: pengodean berjalan bersamaan dengan penggambaran, tanpa tulis-baca file sementara. */
function menuFfmpegPipe(fps, outPath) {
  const p = require("child_process").spawn("ffmpeg", ["-hide_banner", "-loglevel", "error", "-y", "-f", "image2pipe", "-framerate", String(fps), "-c:v", "mjpeg", "-i", "pipe:0",
    "-c:v", "libx264", "-preset", "veryfast", "-crf", "28", "-pix_fmt", "yuv420p", "-r", "16", "-movflags", "+faststart", "-an", outPath], { stdio: ["pipe", "ignore", "pipe"] });
  let err = "";
  p.stderr.on("data", (d) => { err = (err + d).slice(-1500); });
  p.stdin.on("error", () => {});
  const done = new Promise((res, rej) => {
    p.on("error", rej);
    p.on("close", (code) => (code === 0 ? res() : rej(new Error(err.trim().split("\n").slice(-3).join(" | ") || `ffmpeg berhenti dengan kode ${code}`))));
  });
  done.catch(() => {});
  const timer = setTimeout(() => { try { p.kill("SIGKILL"); } catch {} }, 120000);
  done.then(() => clearTimeout(timer), () => clearTimeout(timer));
  return {
    async write(buf) { // menunggu pipa lega (drain), sekaligus memberi napas ke event loop supaya bot tetap responsif
      if (!p.stdin.write(buf)) await Promise.race([new Promise((r) => p.stdin.once("drain", r)), done]);
      else await new Promise((r) => setImmediate(r));
    },
    async end() { p.stdin.end(); await done; },
    kill() { try { p.kill("SIGKILL"); } catch {} },
  };
}
