// Logo bawaan tertanam di sini (JPEG 720 px). Bila ada logo.jpg / logo.png di folder bot, file itu dipakai.
let logoCache = null;
function getLogo() {
  if (logoCache) return logoCache;
  for (const f of ["logo.jpg", "logo.jpeg", "logo.png"]) {
    try { const p = path.join(__dirname, f); if (fs.existsSync(p)) return (logoCache = fs.readFileSync(p)); } catch {}
  }
  return (logoCache = Buffer.from(LOGO_B64, "base64"));
}
const LOGO_B64 = "";

